def render_requirement_index(root: Path, config: dict) -> str:
    version = str(config["current_version"])
    lines = [GENERATED_MARKER, f"# {version} 稳定需求编号", "", "| ID | 类型 | 需求 | 状态 | 权威来源 |", "| --- | --- | --- | --- | --- |"]
    docs = docs_root(root, config)
    for item in sorted(requirement_records(root, config), key=lambda value: str(value.get("id", ""))):
        source = str(item.get("source", "未填写"))
        try:
            source_path = Path(source)
            source_cell = os.path.relpath(source_path, docs / "03-功能规格" / version).replace(os.sep, "/") if source_path.is_absolute() else source
        except ValueError:
            source_cell = source
        lines.append(f"| `{item.get('id', '无')}` | {item.get('type', '未知')} | {item.get('title', '未填写')} | {item.get('status', 'draft')} | {source_cell} |")
    if len(lines) == 4:
        lines.append("| - | - | 当前没有需求 | - | - |")
