def render_trace_matrix(root: Path, config: dict) -> str:
    version = str(config["current_version"])
    lines = [GENERATED_MARKER, f"# {version} 需求追踪矩阵", "", "| 需求 | 功能 | AC | 测试层 | 目标资产 | 证据 |", "| --- | --- | --- | --- | --- | --- |"]
    traced: set[str] = set()
    for record in feature_documents(root, config):
        meta = record["meta"]
        requirement_ids = [meta["id"], *list_field(meta.get("requirements", ""))]
        rows = acceptance_rows(record["text"])
        for requirement_id in requirement_ids:
            traced.add(requirement_id)
            if not rows:
                lines.append(f"| `{requirement_id}` | `{meta['id']}` | 缺失 | 缺失 | 缺失 | 缺失 |")
            for row in rows:
                padded = row + [""] * (8 - len(row))
                lines.append(f"| `{requirement_id}` | `{meta['id']}` | `{padded[0]}` | {padded[4]} | {padded[5]} | {padded[7]} |")
    for item in requirement_records(root, config):
        requirement_id = str(item.get("id", ""))
        if requirement_id and requirement_id not in traced:
            lines.append(f"| `{requirement_id}` | 未映射 | 未映射 | 未映射 | 未映射 | 未映射 |")
    if len(lines) == 4:
        lines.append("| - | 当前没有需求 | - | - | - | - |")
    return "\n".join(lines + [""])


def implementation_points_from_text(text: str) -> list[str]:
    # front matter 中的 forbidden_paths 是授权约束，不是实现落点；先剥离，避免自相冲突。
    body = text
    lines = text.splitlines()
    if lines and lines[0].strip() == "---":
        for index, line in enumerate(lines[1:], start=1):
            if line.strip() == "---":
                body = "\n".join(lines[index + 1 :])
                break
    return sorted(set(IMPLEMENTATION_PATH_RE.findall(body)))


def implementation_layer(path: str) -> str:
    lowered = path.lower()
    if any(marker in lowered for marker in ["migration", "migrations", "schema", "/sql/", "/db/", "database", "models/"]):
        return "data"
    if path.startswith(("app/", "client/", "web/", "frontend/")) or any(marker in lowered for marker in ["frontend", "/web/", "/ui/", "components/"]):
        return "frontend"
    if path.startswith(("test/", "tests/", "spec/", "specs/")):
        return "test"
    return "backend"


def feature_implementation_signal(root: Path, record: dict) -> dict:
    points = implementation_points_from_text(record["text"])
    paths = {
        layer: [path for path in points if implementation_layer(path) == layer]
        for layer in ["backend", "frontend", "data", "test"]
    }
    existing = {
        layer: [path for path in values if (root / path).exists()]
        for layer, values in paths.items()
    }
    feature_status = str(record["meta"].get("status", "draft"))

    def layer_status(layer: str) -> str:
        declared = paths[layer]
        present = existing[layer]
        if not declared:
            return "unknown"
        if not present:
            return "not_started" if feature_status in {"planning", "draft", "ready"} else "unknown"
        if feature_status == "implementing":
            return "implementing"
        if feature_status in {"local_verified", "staging_verified", "released"}:
            return "implemented"
        return "unknown"

    rows = acceptance_rows(record["text"])
    evidenced = sum(1 for row in rows if len(row) >= 8 and not incomplete(row[7]))
    missing_paths = [path for path in points if not (root / path).exists()]
    if not points:
        gap = "功能文档未声明可解析的工程落点"
    elif missing_paths:
        gap = f"{len(missing_paths)} 个声明的工程落点尚不存在"
    elif feature_status in {"local_verified", "staging_verified", "released"}:
        gap = "代码落点存在；仍以当前提交绑定的机器证据为准"
    else:
        gap = "代码落点存在；功能状态或机器证据尚未证明实现完成"
    return {
        "backend": layer_status("backend"),
        "frontend": layer_status("frontend"),
        "data": layer_status("data"),
        "automated_verification": "evidence_linked" if rows and evidenced == len(rows) else "not_run",
        "gap": gap,
        "evidence": f"{evidenced}/{len(rows)} AC 已登记证据入口" if rows else "未建立 AC",
        "paths": paths,
        "existing_paths": existing,
        "missing_paths": missing_paths,
    }


