def svg_flow(title: str, labels: list[str], subtitle: str) -> str:
    safe_title = html.escape(title)
    safe_subtitle = html.escape(subtitle)
    normalized = labels or ["待完成项目调研"]
    width = 1280
    row_height = 92
    height = 150 + row_height * len(normalized)
    blocks = [
        '<!-- generated by daoge-docs; 请修改权威源后运行 index，不要直接编辑 -->',
        f'<svg xmlns="http://www.w3.org/2000/svg" width="{width}" height="{height}" viewBox="0 0 {width} {height}">',
        '<rect width="100%" height="100%" fill="#f8fafc"/>',
        '<style>text{font-family:-apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei",sans-serif;fill:#17202a}.title{font-size:28px;font-weight:700}.sub{font-size:14px;fill:#566573}.item{font-size:17px;font-weight:600}.note{font-size:13px;fill:#566573}</style>',
        f'<text x="48" y="48" class="title">{safe_title}</text>',
        f'<text x="48" y="76" class="sub">{safe_subtitle}</text>',
    ]
    for index, label in enumerate(normalized):
        y = 104 + index * row_height
        fill = "#e8f5e9" if index == 0 else "#eef3f7"
        blocks.append(f'<rect x="48" y="{y}" width="1184" height="64" rx="4" fill="{fill}" stroke="#aab7b8"/>')
        blocks.append(f'<text x="72" y="{y + 29}" class="item">{html.escape(label)}</text>')
        blocks.append(f'<text x="72" y="{y + 50}" class="note">来源：DAOGE Docs 当前权威文档与注册表</text>')
        if index < len(normalized) - 1:
            blocks.append(f'<path d="M640 {y + 64} V{y + 88}" stroke="#566573" stroke-width="2"/>')
            blocks.append(f'<path d="M634 {y + 82} L640 {y + 89} L646 {y + 82}" fill="none" stroke="#566573" stroke-width="2"/>')
    blocks.append("</svg>")
    return "\n".join(blocks) + "\n"


def future_version_plan_records(root: Path, config: dict) -> list[dict]:
    """Discover one explicit planning entry per future version.

    New projects use ``后续版本/Vn-名称/Vn-版本总览.md``.  The legacy flat
    ``后续版本/Vn-名称.md`` shape remains readable so an upgrade never loses
    an existing planning decision.  Supplementary files under a planning
    directory are intentionally not treated as a second version authority.
    """
    base = docs_root(root, config) / "02-产品与版本" / "后续版本"
    if not base.exists():
        return []
    candidates: set[Path] = {
        path for path in base.glob("V*-*.md") if path.name != "README.md"
    }
    candidates.update(path for path in base.rglob("V*-版本总览.md") if path.name != "README.md")
    records: list[dict] = []
    for path in sorted(candidates):
        text = path.read_text(encoding="utf-8")
        meta = parse_frontmatter(text)
        version = str(meta.get("version", "")).strip().upper()
        if not version:
            match = re.match(r"^(V\d+)-", path.name, re.IGNORECASE)
            version = match.group(1).upper() if match else ""
        if not re.fullmatch(r"V\d+", version):
            continue
        records.append(
            {
                "version": version,
                "path": path,
                "status": str(meta.get("status", "planning")),
                "title": markdown_title(text),
                "formal": path.name == f"{version}-版本总览.md",
            }
        )
    return records


def future_version_documents(root: Path, config: dict) -> list[Path]:
    return [item["path"] for item in future_version_plan_records(root, config)]


def registered_version_rows(root: Path, config: dict) -> list[dict]:
    """Read the version registry used by all project-wide surfaces."""
    table = browser_structured_table(root, config, "version_sequence")
    if table["status"] == "ready":
        return table["rows"]
    return []


def registered_version_ids(root: Path, config: dict) -> list[str]:
    """Return stable version IDs from the roadmap, with filesystem fallback."""
    ids: list[str] = []
    for row in registered_version_rows(root, config):
        version_id = str(row.get("版本 ID", "")).strip().upper()
        if version_id and version_id not in ids:
            ids.append(version_id)
    feature_root = docs_root(root, config) / "03-功能规格"
    if feature_root.exists():
        discovered = [path.name.upper() for path in feature_root.iterdir() if path.is_dir() and re.fullmatch(r"V\d+", path.name, re.IGNORECASE)]
        for version_id in sorted(discovered, key=lambda value: (int(value[1:]), value)):
            if version_id not in ids:
                ids.append(version_id)
    for plan in future_version_plan_records(root, config):
        version_id = str(plan["version"])
        if version_id not in ids:
            ids.append(version_id)
    current = str(config["current_version"]).upper()
    if current not in ids:
        ids.insert(0, current)
    return ids


def render_version_flow_svg(root: Path, config: dict) -> str:
    rows = registered_version_rows(root, config)
    labels = [f"{row.get('版本 ID', '未声明')}：{row.get('目标', '版本目标未登记')}" for row in rows]
    if not labels:
        labels = [f"{config['current_version']}：当前版本"]
    return svg_flow("功能演进：版本主链路", labels, "版本顺序来自版本路线图；当前执行版本与后续规划的门禁、证据分别计算。")


def render_capability_heatmap_svg(root: Path, config: dict) -> str:
    counts: dict[str, int] = {}
    for record in all_feature_documents(root, config):
        domain = record["meta"].get("domain", "未分类")
        counts[domain] = counts.get(domain, 0) + 1
    labels = [f"{domain}：{count} 个功能" for domain, count in sorted(counts.items())]
    return svg_flow("功能演进：能力热力图", labels, "能力数量覆盖版本路线图登记的全部功能；颜色不表达完成状态。")


def render_gate_flow_svg() -> str:
    return svg_flow(
        "功能演进：门禁依赖图",
        ["Discovery：项目事实闭环", "Version Ready：版本输入闭环", "Feature Ready：单功能可实现", "Release：当前构建证据闭环"],
        "任一上游门禁失败时，下游阶段不得通过。",
    )


def browser_excerpt(text: str, heading: str | None = None) -> str:
    lines = text.splitlines()
    start = 0
    if lines and lines[0].strip() == "---":
        for index, line in enumerate(lines[1:], start=1):
            if line.strip() == "---":
                start = index + 1
                break
    if heading:
        for index, line in enumerate(lines[start:], start=start):
            if re.match(r"^#{1,6}\s+", line) and heading in line:
                start = index + 1
                break
    paragraphs: list[str] = []
    current: list[str] = []
    for line in lines[start:]:
        stripped = line.strip()
        if stripped == "---" or stripped.startswith("#") or stripped.startswith("|") or stripped.startswith("```"):
            if current:
                paragraphs.append(" ".join(current))
                current = []
            if paragraphs or (heading and stripped.startswith("#")):
                break
            continue
        if not stripped:
            if current:
                paragraphs.append(" ".join(current))
                current = []
            if paragraphs:
                break
            continue
        if stripped.startswith(("- ", "* ", "> ")):
            stripped = stripped[2:].strip()
        current.append(stripped)
    if current:
        paragraphs.append(" ".join(current))
    excerpt = re.sub(r"[`*_\[\]()]", "", paragraphs[0] if paragraphs else "")
    return excerpt[:240]


def browser_section_index(path: str, text: str) -> list[dict]:
    """Build deterministic section anchors without changing document content."""
    lines = text.splitlines()
    sections: list[dict] = []
    stack: list[dict] = []
    sibling_counts: dict[tuple[str, str], int] = {}
    for line_number, line in enumerate(lines, start=1):
        match = re.match(r"^(#{1,6})\s+(.+)$", line)
        if not match:
            continue
        level = len(match.group(1))
        title = match.group(2).strip()
        while stack and stack[-1]["level"] >= level:
            stack[-1]["line_end"] = line_number - 1
            stack.pop()
        parent_id = stack[-1]["id"] if stack else ""
        count_key = (parent_id, title)
        occurrence = sibling_counts.get(count_key, 0) + 1
        sibling_counts[count_key] = occurrence
        stable_key = f"{path}|{parent_id}|{title}|{occurrence}"
        section_id = f"SEC-{hashlib.sha256(stable_key.encode('utf-8')).hexdigest()[:12].upper()}"
        section = {
            "id": section_id,
            "title": title,
            "level": level,
            "parent_id": parent_id,
            "line_start": line_number,
            "line_end": len(lines),
            "order": len(sections),
        }
        sections.append(section)
        stack.append(section)
    for section in stack:
        section["line_end"] = len(lines)
    return sections


def document_version_scope(relative: Path, meta: dict) -> str:
    """Return a document's explicit structural version scope, never prose inference."""
    declared = clean_markdown_cell(meta.get("version", "")).strip()
    if declared:
        return declared
    for part in relative.parts:
        if re.fullmatch(r"V[0-9]+", part, flags=re.IGNORECASE):
            return part.upper()
    match = re.match(r"^(V[0-9]+)-", relative.name, flags=re.IGNORECASE)
    return match.group(1).upper() if match else ""


def browser_records(root: Path, config: dict) -> list[dict]:
    docs = docs_root(root, config)
    records: list[dict] = []
    supported = {".md", ".yaml", ".yml", ".json"}
    for path in sorted(item for item in docs.rglob("*") if item.is_file() and item.suffix.lower() in supported):
        relative = path.relative_to(docs)
        if "报告" in relative.parts and path.suffix.lower() == ".json":
            continue
        text = path.read_text(encoding="utf-8")
        is_markdown = path.suffix.lower() == ".md"
        meta = parse_frontmatter(text) if is_markdown else {}
        generated = GENERATED_MARKER in text[:200]
        if not is_markdown:
            document_status = "not_applicable"
            status_source = "structured_file"
        elif meta.get("status"):
            document_status = meta["status"]
            status_source = "frontmatter"
        elif generated:
            document_status = "generated"
            status_source = "generated_marker"
        else:
            document_status = "unknown"
            status_source = "missing_frontmatter"
        sections = browser_section_index(relative.as_posix(), text)
        headings = [{"level": item["level"], "title": item["title"], "id": item["id"]} for item in sections]
        records.append(
            {
                "id": relative.as_posix(),
                "path": relative.as_posix(),
                "title": markdown_title(text) if is_markdown else path.name,
                "status": document_status,
                "status_source": status_source,
                "authority": meta.get("authority", "未声明"),
                "owner": meta.get("owner", "未声明"),
                "updated": meta.get("updated", "未声明"),
                "stable_id": meta.get("id") or meta.get("doc_id") or meta.get("spec_id") or "",
                "version": document_version_scope(relative, meta),
                "category": relative.parts[0],
                "directory_id": relative.parent.as_posix() if relative.parent.as_posix() != "." else ".",
                "kind": path.suffix.lower().lstrip("."),
                "content": text,
                "headings": headings,
                "sections": sections,
                "content_digest": f"sha256:{hashlib.sha256(text.encode('utf-8')).hexdigest()}",
                "line_count": len(text.splitlines()),
                "character_count": len(text),
                "excerpt": browser_excerpt(text),
                "generated": generated,
            }
        )
    return records


def enrich_browser_source_sections(value: object, documents: list[dict]) -> None:
    """Attach section IDs to existing source references when a title is exact.

    Older source records remain valid because source_section is intentionally
    retained as the human-readable and compatibility fallback.
    """
    section_ids: dict[tuple[str, str], str] = {}
    for document in documents:
        path = str(document.get("path", ""))
        for section in document.get("sections") or []:
            title = str(section.get("title", "")).strip()
            section_id = str(section.get("id", "")).strip()
            if path and title and section_id:
                section_ids.setdefault((path, title), section_id)
    if isinstance(value, dict):
        source_path = str(value.get("source_path", "")).strip()
        source_section = str(value.get("source_section", "")).strip()
        if source_path and source_section and not value.get("source_section_id"):
            section_id = section_ids.get((source_path, source_section))
            if section_id:
                value["source_section_id"] = section_id
        for item in value.values():
            enrich_browser_source_sections(item, documents)
    elif isinstance(value, list):
        for item in value:
            enrich_browser_source_sections(item, documents)


def browser_directories(root: Path, config: dict, documents: list[dict]) -> list[dict]:
    """Build the recursive developer-facing directory model.

    README/index files remain authority navigation documents; this model only
    records where they live and never copies their business conclusions.
    """
    docs = docs_root(root, config)
    directory_paths: set[Path] = {Path(".")}
    if docs.exists():
        for path in sorted(item for item in docs.rglob("*") if item.is_dir()):
            directory_paths.add(path.relative_to(docs))
    for document in documents:
        directory = Path(document["directory_id"])
        while directory != Path("."):
            directory_paths.add(directory)
            directory = directory.parent

    readme_names = {
        "README.md",
        "导航文档.md",
        "索引.md",
        "功能规格索引.md",
        "技术设计索引.md",
        "用例矩阵.md",
    }
    document_counts: dict[str, int] = {}
    for document in documents:
        parts = Path(document["directory_id"])
        while True:
            key = parts.as_posix() if parts.as_posix() != "." else "."
            document_counts[key] = document_counts.get(key, 0) + 1
            if parts == Path("."):
                break
            parts = parts.parent

    result: list[dict] = []
    for directory in sorted(directory_paths, key=lambda item: (len(item.parts), item.as_posix())):
        relative = directory.as_posix() if directory.as_posix() != "." else "."
        absolute = docs / directory
        readme = next(
            (
                child
                for child in sorted(absolute.iterdir(), key=lambda item: item.name)
                if child.is_file() and child.name in readme_names
            ),
            None,
        ) if absolute.exists() else None
        children = [
            child.as_posix()
            for child in sorted(directory_paths, key=lambda item: item.as_posix())
            if child != directory and child.parent == directory
        ]
        result.append(
            {
                "id": relative,
                "path": relative,
                "parent_id": directory.parent.as_posix() if relative != "." else None,
                "name": "文档根目录" if relative == "." else directory.name,
                "readme_path": readme.relative_to(docs).as_posix() if readme else "",
                # Populated directories need a visible navigation entry even
                # when they do not carry a README; empty artifact folders stay
                # physical-only.
                "kind": "semantic" if readme or document_counts.get(relative, 0) or children else "artifact",
                "authority": "目录导航与阅读入口" if readme else "未声明",
                "document_count": document_counts.get(relative, 0),
                "child_count": len(children),
                "child_ids": children,
                "status": "未评估",
                "finding_count": 0,
            }
        )
    return result


def _finding(
    *,
    rule_id: str,
    stage: str,
    severity: str,
    object_type: str,
    object_id: str,
    title: str,
    reason: str,
    source_path: str,
    source_section: str,
    recovery_action: str,
    verification_command: str = "",
    evidence_type: str = "",
    owner: str = "未声明",
    authority_digest_value: str = "",
) -> dict:
    return {
        "rule_id": rule_id,
        "stage": stage,
        "severity": severity,
        "status": "open",
        "object_type": object_type,
        "object_id": object_id,
        "title": title,
        "reason": reason,
        "source_path": source_path,
        "source_section": source_section,
        "owner": owner or "未声明",
        "recovery_action": recovery_action,
        "verification_command": verification_command,
        "evidence_type": evidence_type,
        "authority_digest": authority_digest_value,
    }


def browser_findings(
    root: Path,
    config: dict,
    documents: list[dict],
    directories: list[dict],
    features: list[dict],
    governance: dict,
    authority_digest_value: str,
) -> list[dict]:
    """Return itemized, deterministic findings shared by all workbench views."""
    findings: list[dict] = []
    python_command = project_python_command()
    adr_records = {str(record["meta"].get("id", "")): record for record in adr_documents(root, config)}
    approval = governance.get("approval", {})
    approval_blocker = str(approval.get("blocking_reason", ""))
    if approval_blocker:
        findings.append(
            _finding(
                rule_id="VERSION-APPROVAL",
                stage="version-ready",
                severity="blocking",
                object_type="approval",
                object_id="version_scope",
                title="当前版本尚未获得有效开发确认",
                reason=approval_blocker,
                source_path="01-项目概览/项目输入与约束注册表.json",
                source_section="approvals",
                recovery_action=str(approval.get("recovery_action", "提出并由开发者确认当前版本范围。")),
                verification_command=f"{python_command} .daoge-docs/daoge_docs.py gate --root . --stage version-ready",
                owner="版本负责人",
                authority_digest_value=authority_digest_value,
            )
        )
    for gate in governance.get("gates", []):
        for signal in gate.get("blocking_signals", []):
            # The feature-level finding below names the exact ADR and recovery path.
            # Keep the aggregated gate signal on its card, but do not duplicate it in
            # the selected feature's action list or Goal blockers.
            if gate.get("id") in {"version-ready", "feature-ready"} and re.fullmatch(r"\d+ 个功能依赖的 ADR 尚未接受", str(signal)):
                continue
            if gate.get("id") == "version-ready" and str(signal) == approval_blocker:
                continue
            findings.append(
                _finding(
                    rule_id=f"GATE-{str(gate['id']).upper()}",
                    stage=str(gate["id"]),
                    severity="blocking",
                    object_type="gate",
                    object_id=str(gate["id"]),
                    title=f"{gate['label']} 仍有结构阻塞",
                    reason=str(signal),
                    source_path=str(gate.get("path", "")),
                    source_section="门禁输入",
                    recovery_action=f"打开 {gate['label']} 门禁入口，逐项补齐缺失文档、状态或追踪关系。",
                    verification_command=f"{python_command} .daoge-docs/daoge_docs.py gate --root . --stage {gate['id']}",
                    owner="门禁负责人",
                    authority_digest_value=authority_digest_value,
                )
            )
    for evidence in governance.get("evidence", []):
        if evidence.get("selected") and evidence.get("result") == "passed" and evidence.get("freshness") == "stale":
            findings.append(
                _finding(
                    rule_id="EVIDENCE-FRESHNESS",
                    stage="release",
                    severity="blocking",
                    object_type="evidence",
                    object_id=str(evidence.get("type", "unknown")),
                    title=f"{evidence.get('type', 'unknown')} 证据已过期",
                    reason="当前权威摘要或 Git 提交已经与报告绑定值不一致，不能继续作为当前交付证明。",
                    source_path=str(evidence.get("path", "")),
                    source_section="提交/构建绑定",
                    recovery_action="重新执行该证据类型并绑定当前提交、构建和 authority_digest。",
                    verification_command=chain_project_commands(
                        f"{python_command} .daoge-docs/daoge_docs.py index --root .",
                        f"{python_command} .daoge-docs/daoge_docs.py gate --root . --stage release",
                    ),
                    evidence_type=str(evidence.get("type", "")),
                    authority_digest_value=authority_digest_value,
                )
            )
    for feature in features:
        feature_id = str(feature.get("id", ""))
        if not feature_id:
            continue
        source_path = str(feature.get("path", ""))
        for decision_id in feature.get("decisions", []):
            if not str(decision_id).startswith("ADR-"):
                continue
            adr = adr_records.get(str(decision_id))
            adr_status = str(adr["meta"].get("status", "proposed")) if adr else "missing"
            adr_source_path = adr["path"].relative_to(docs_root(root, config)).as_posix() if adr else source_path
            if adr_status == "accepted":
                continue
            reason = (
                f"功能引用未知 ADR：{feature_id} -> {decision_id}"
                if not adr
                else f"功能依赖的 ADR 尚未接受：{feature_id} -> {decision_id}：{adr_status}"
            )
            findings.append(
                _finding(
                    rule_id="FEATURE-ADR-ACCEPTANCE",
                    stage="feature-ready",
                    severity="blocking",
                    object_type="feature",
                    object_id=feature_id,
                    title="功能依赖的 ADR 尚未冻结",
                    reason=reason,
                    source_path=adr_source_path,
                    source_section="决策",
                    recovery_action=(
                        f"补充并接受 {decision_id}，记录有权确认人和确认时间；随后运行 index、check 和 Feature Ready gate。"
                        if adr
                        else f"创建或修正 {decision_id} 的 ADR 引用，然后重新运行 index、check 和 Feature Ready gate。"
                    ),
                    verification_command=f"{python_command} .daoge-docs/daoge_docs.py gate --root . --stage feature-ready --feature {feature_id} --json",
                    owner=str(feature.get("owner", "未声明")),
                    authority_digest_value=authority_digest_value,
                )
            )
        if feature.get("status") not in READY_STATUSES:
            findings.append(
                _finding(
                    rule_id="FEATURE-STATUS",
                    stage="feature-ready",
                    severity="blocking",
                    object_type="feature",
                    object_id=feature_id,
                    title="功能尚未进入可实现状态",
                    reason=f"功能状态为 {feature.get('status', '未声明')}，不属于 Feature Ready 允许状态。",
                    source_path=source_path,
                    source_section="功能卡",
                    recovery_action="补齐功能范围、契约、验收与验证记录，并将状态推进到 ready 或后续已验证状态。",
                    verification_command=f"{python_command} .daoge-docs/daoge_docs.py gate --root . --stage feature-ready --feature {feature_id}",
                    owner=str(feature.get("owner", "未声明")),
                    authority_digest_value=authority_digest_value,
                )
            )
        if not feature.get("design_structure_complete"):
            findings.append(
                _finding(
                    rule_id="FEATURE-DESIGN-DEPTH",
                    stage="feature-ready",
                    severity="blocking",
                    object_type="feature",
                    object_id=feature_id,
                    title="功能设计深度未闭环",
                    reason="函数契约、可执行伪代码、稳定分支或 AC 追踪至少有一项缺失。",
                    source_path=source_path,
                    source_section="技术设计",
                    recovery_action="补齐设计章节和稳定分支追踪；高风险功能同时补齐独立技术设计。",
                    verification_command=f"{python_command} .daoge-docs/daoge_docs.py check --root . --json",
                    owner=str(feature.get("owner", "未声明")),
                    authority_digest_value=authority_digest_value,
                )
            )
        if feature.get("has_placeholders"):
            findings.append(
                _finding(
                    rule_id="DOCUMENT-PLACEHOLDER",
                    stage="feature-ready",
                    severity="blocking",
                    object_type="feature",
                    object_id=feature_id,
                    title="功能文档仍有待决占位",
                    reason="权威功能文档或其高风险技术设计包含待填写、TODO 或 TBD。",
                    source_path=source_path,
                    source_section="正文",
                    recovery_action="将未知项写成明确的待确认事实，补充负责人和截止条件后重新运行 check。",
                    verification_command=f"{python_command} .daoge-docs/daoge_docs.py check --root . --json",
                    owner=str(feature.get("owner", "未声明")),
                    authority_digest_value=authority_digest_value,
                )
            )
        if feature.get("risk") == "high" and not feature.get("has_design"):
            findings.append(
                _finding(
                    rule_id="HIGH-RISK-DESIGN",
                    stage="feature-ready",
                    severity="blocking",
                    object_type="feature",
                    object_id=feature_id,
                    title="高风险功能缺少独立技术设计",
                    reason="高风险功能必须有同名 -技术设计.md，当前入口不存在。",
                    source_path=source_path,
                    source_section="风险分级",
                    recovery_action="创建并完成独立高风险技术设计，再重新运行 index 和 feature-ready gate。",
                    verification_command=f"{python_command} .daoge-docs/daoge_docs.py gate --root . --stage feature-ready --feature {feature_id}",
                    owner=str(feature.get("owner", "未声明")),
                    authority_digest_value=authority_digest_value,
                )
            )
    for directory in directories:
        if directory["id"] != "." and directory.get("kind") == "semantic" and not directory.get("readme_path"):
            findings.append(
                _finding(
                    rule_id="DIRECTORY-README",
                    stage="discovery",
                    severity="high",
                    object_type="directory",
                    object_id=str(directory["id"]),
                    title="目录缺少 README 或索引入口",
                    reason="每个语义目录都需要一个导航入口，避免 AI 和开发者依赖目录猜测职责。",
                    source_path=str(directory["path"]),
                    source_section="目录结构",
                    recovery_action="在目录内创建 README.md 或索引文档，并声明职责、权威分工和阅读路径。",
                    verification_command=f"{python_command} .daoge-docs/daoge_docs.py check --root . --json",
                    authority_digest_value=authority_digest_value,
                )
            )
    findings.sort(key=lambda item: (item["stage"], item["object_type"], item["object_id"], item["rule_id"], item["reason"]))
    for index, finding in enumerate(findings, start=1):
        finding["id"] = f"WB-F-{index:04d}"
    return findings


DEVELOPMENT_WORKBENCH_STAGES = {"discovery", "version-ready", "feature-ready"}


def workbench_development_findings(findings: list[dict], feature_id: str = "") -> list[dict]:
    """Return findings that can prevent starting work on the selected feature.

    Release is intentionally excluded. A failed Release gate prevents publishing the
    current build; it must never retroactively withdraw an already-ready development
    authorization.
    """
    relevant: list[dict] = []
    for item in findings:
        if item.get("status") != "open" or item.get("stage") not in DEVELOPMENT_WORKBENCH_STAGES:
            continue
        if item.get("object_id") == feature_id or item.get("object_type") in {"gate", "approval"}:
            relevant.append(item)
    return relevant


def browser_relations(
    documents: list[dict],
    directories: list[dict],
    features: list[dict],
    requirements: list[dict],
    decisions: list[dict],
    adrs: list[dict],
    e2e: list[dict],
    versions: list[dict],
    task_packets: list[dict],
) -> list[dict]:
    entities: set[str] = {item["path"] for item in documents}
    entities.update(item["id"] for item in directories)
    entities.update(item["id"] for item in features if item.get("id"))
    entities.update(item["id"] for item in requirements if item.get("id"))
    entities.update(item["id"] for item in decisions if item.get("id"))
    entities.update(item["id"] for item in adrs if item.get("id"))
    entities.update(item["id"] for item in e2e if item.get("id"))
    entities.update(item["id"] for item in versions if item.get("id"))
    entities.update(item["id"] for item in task_packets if item.get("id"))
    relations: list[dict] = []

    def add(from_id: str, to_id: str, relation: str, source_path: str, source_section: str) -> None:
        if from_id and to_id and from_id in entities and to_id in entities and from_id != to_id:
            source = {
                "source_path": source_path,
                "source_section": source_section,
                "source_id": from_id,
                "authority": "派生追踪关系",
            }
            relations.append(
                {
                    "from": from_id,
                    "to": to_id,
                    "relation": relation,
                    "label": relation,
                    "source_path": source_path,
                    "source_section": source_section,
                    "sources": [source],
                }
            )

    for directory in directories:
        parent = directory.get("parent_id")
        if parent is not None:
            add(parent, directory["id"], "contains", directory["readme_path"] or directory["path"], "目录结构")
        for document in documents:
            if document.get("directory_id") == directory["id"]:
                add(directory["id"], document["path"], "contains", document["path"], "目录结构")
    requirement_ids = {item.get("id") for item in requirements}
    for feature in features:
        source = feature.get("path", "")
        feature_id = feature.get("id", "")
        for requirement in feature.get("requirements", []):
            if requirement in requirement_ids:
                add(feature_id, requirement, "satisfies", source, "front matter")
        for decision in feature.get("decisions", []):
            add(feature_id, decision, "decided_by", source, "来源与追踪")
        for dependency in feature.get("dependencies", []):
            add(feature_id, dependency, "depends_on", source, "前置依赖")
        for acceptance in feature.get("acceptance", []):
            acceptance_id = f"{feature_id}:{acceptance['id']}"
            entities.add(acceptance_id)
            add(feature_id, acceptance_id, "has_acceptance", source, "验收标准")
            for branch in feature.get("branches", []):
                if acceptance["id"] in branch.get("acceptance_ids", []):
                    entities.add(branch["id"])
                    add(acceptance_id, branch["id"], "traced_by", source, "分支到测试追踪")
            for test in e2e:
                if acceptance["id"] in test.get("acceptance", []) or feature_id in test.get("requirements", []):
                    add(acceptance_id, test["id"], "traced_by", test.get("path", ""), "E2E 需求")
        for version in feature.get("future_versions", []):
            add(feature_id, version, "planned_for", source, "版本规划")
        task_id = f"WB-TASK-{feature_id}"
        add(feature_id, task_id, "implemented_by", source, "实现与验证")
    for item in e2e:
        for requirement in item.get("requirements", []):
            add(requirement, item["id"], "traced_by", item.get("path", ""), "E2E 需求")
    for item in decisions:
        source = item.get("source_path", "")
        for requirement in item.get("requirements", []):
            add(requirement, item["id"], "decided_by", source, "决策注册表")
    for item in adrs:
        for requirement in item.get("requirements", []):
            add(requirement, item["id"], "decided_by", item.get("path", ""), "ADR front matter")
    dedupe: dict[tuple[str, str, str, str, str], dict] = {}
    for relation in relations:
        key = (relation["from"], relation["to"], relation["relation"], relation["source_path"], relation["source_section"])
        dedupe[key] = relation
    return sorted(dedupe.values(), key=lambda item: (item["from"], item["relation"], item["to"], item["source_path"]))


def browser_task_packets(
    features: list[dict],
    findings: list[dict],
    authority_digest_value: str,
    current_version: str,
    generated_at: str,
) -> list[dict]:
    packets: list[dict] = []
    version_blockers = [
        item["id"]
        for item in findings
        if item.get("status") == "open"
        and item.get("object_type") in {"gate", "approval"}
        and item.get("stage") in {"discovery", "version-ready"}
        and item.get("severity") in {"blocking", "high"}
    ]
    for feature in features:
        feature_id = feature.get("id", "")
        if not feature_id:
            continue
        blockers = version_blockers + [
            item["id"]
            for item in workbench_development_findings(findings, str(feature_id))
            if item.get("object_id") == feature_id and item.get("severity") in {"blocking", "high"}
        ]
        commands: list[str] = []
        acceptance = []
        for item in feature.get("acceptance", []):
            command = item.get("command", "")
            if command and command not in commands:
                commands.append(command)
            acceptance.append(item)
        packets.append(
            {
                "id": f"WB-TASK-{feature_id}",
                "feature_id": feature_id,
                "version": current_version,
                "authority_digest": authority_digest_value,
                "generated_at": generated_at,
                "status": "ready" if not blockers and feature.get("status") in READY_STATUSES else "blocked",
                "scope": {"summary": feature.get("summary", ""), "non_goals": feature.get("non_goals", [])},
                "requirements": feature.get("requirements", []),
                "decisions": feature.get("decisions", []),
                "dependencies": feature.get("dependencies", []),
                "acceptance": acceptance,
                "branches": feature.get("branches", []),
                "implementation_points": feature.get("implementation_points", []),
                "forbidden_paths": feature.get("forbidden_paths", []),
                "blocker_ids": blockers,
                "verification_commands": commands,
                "forbidden_actions": [
                    "不得超出功能边界实现未授权能力。",
                    "不得绕过门禁、伪造或覆盖机器证据。",
                    *[f"不得修改 {path} 或其子路径。" for path in feature.get("forbidden_paths", [])],
                ],
                "source_paths": [feature.get("path", "")] + ([feature.get("design_path", "")] if feature.get("design_path") else []),
                "source_path": feature.get("path", ""),
                "source_section": "实现与验证",
            }
        )
    return packets


def browser_execution_plan(task_packets: list[dict]) -> dict:
    """Expose the same conservative lane plan used by ``prepare-goal``."""
    tasks = []
    for sequence, packet in enumerate(task_packets, start=1):
        feature_id = str(packet.get("feature_id", ""))
        tasks.append(
            {
                "task_id": f"TASK-{feature_id}",
                "sequence": sequence,
                "dependencies": [f"TASK-{item}" for item in packet.get("dependencies", [])],
                "allowed_paths": [item for item in packet.get("implementation_points", []) if valid_goal_path(str(item))],
                "forbidden_paths": list(packet.get("forbidden_paths", [])),
            }
        )
    plan = plan_goal_execution(tasks)
    packet_by_task = {f"TASK-{item.get('feature_id', '')}": item for item in task_packets}
    for lane in plan.get("lanes", []):
        for task_id in lane.get("task_ids", []):
            packet = packet_by_task.get(task_id)
            if packet is not None:
                packet["parallel_group"] = lane["lane_id"]
                packet["parallel_eligible"] = lane["parallel"]
                packet["parallel_reason"] = lane["reason"]
    return plan


def browser_evidence(root: Path, config: dict, current_authority_digest: str | None = None) -> list[dict]:
    current_digest = current_authority_digest or authority_digest(root, config)[0]
    current_commit = git_head(root) or ""
    selector_path = root / ".daoge-docs" / "evidence.json"
    selected: dict = {}
    if selector_path.exists():
        selector = read_json(selector_path, "当前证据清单")
        if isinstance(selector.get("selected"), dict):
            selected = selector["selected"]
    summaries: list[dict] = []
    for evidence_type in sorted(EVIDENCE_TYPES):
        raw_path = selected.get(evidence_type)
        report: dict = {}
        display_path = ""
        if raw_path:
            path = root / str(raw_path)
            if path.exists():
                report = read_json(path, f"{evidence_type} 证据报告")
                display_path, _ = normalize_doc_source(root, config, path)
        report_digest = str(report.get("authority_digest") or (report.get("approval") or {}).get("authority_digest") or "")
        report_commit = str(report.get("commit") or "")
        commit_matches = None if not current_commit or not report_commit else bool(
            current_commit.startswith(report_commit) or report_commit.startswith(current_commit)
        )
        authority_matches = None if not report_digest else report_digest == current_digest
        freshness_reasons: list[str] = []
        if report.get("result") == "passed":
            if authority_matches is False:
                freshness_reasons.append("权威文档摘要已变化")
            if commit_matches is False:
                freshness_reasons.append("证据提交与当前 HEAD 不一致")
            if not report_digest:
                freshness_reasons.append("报告未绑定 authority_digest")
            freshness = "fresh" if not freshness_reasons and commit_matches is not False else "stale"
        else:
            freshness = "unknown"
        summaries.append(
            {
                "type": evidence_type,
                "path": display_path or str(raw_path or ""),
                "selected": bool(raw_path),
                "result": report.get("result", "not_run"),
                "environment": report.get("environment", "未声明"),
                "commit": report.get("commit", ""),
                "build_id": report.get("build_id", ""),
                "executed_at": report.get("executed_at", ""),
                "command_count": len(report.get("commands", [])) if isinstance(report.get("commands"), list) else 0,
                "check_count": len(report.get("checks", [])) if isinstance(report.get("checks"), list) else 0,
                "authority_digest": report_digest,
                "authority_matches": authority_matches,
                "commit_matches_head": commit_matches,
                "freshness": freshness,
                "freshness_reasons": freshness_reasons,
            }
        )
    return summaries


def browser_governance(root: Path, config: dict, features: list[dict], current_authority_digest: str | None = None) -> dict:
    docs = docs_root(root, config)
    values = values_for(config)
    approval = version_scope_approval(root, config)
    change_sets = [
        change_set_summary(root, config, item)
        for item in change_set_records(project_inputs(root, config))
        if str(item.get("version", "")) == str(config["current_version"])
    ]
    spec_drafts = [
        spec_draft_summary(root, config, item)
        for item in spec_draft_records(project_inputs(root, config))
        if str(item.get("version", "")) == str(config["current_version"])
    ]
    gate_definitions = [
        ("discovery", "Discovery", {"discovery"}),
        ("version-ready", "Version Ready", {"discovery", "version-ready"}),
        ("feature-ready", "Feature Ready", set()),
        ("release", "Release", {"release"}),
    ]
    adr_status_by_id = adr_statuses(root, config)
    unresolved_feature_adrs = {
        (str(feature.get("id", "")), str(decision_id))
        for feature in features
        for decision_id in feature.get("decisions", [])
        if str(decision_id).startswith("ADR-") and adr_status_by_id.get(str(decision_id)) != "accepted"
    }
    gates = []
    for gate_id, label, stages in gate_definitions:
        if gate_id == "feature-ready":
            total = len(features)
            ready = sum(1 for item in features if item["status"] in READY_STATUSES and item["design_structure_complete"])
            placeholders = sum(1 for item in features if item["has_placeholders"])
            blockers = []
            if not total:
                blockers.append("当前版本没有功能规格")
            if total - ready:
                blockers.append(f"{total - ready} 个功能尚未达到结构就绪")
            if placeholders:
                blockers.append(f"{placeholders} 个功能仍有待决占位")
            if unresolved_feature_adrs:
                blockers.append(f"{len(unresolved_feature_adrs)} 个功能依赖的 ADR 尚未接受")
            path = f"03-功能规格/{config['current_version']}/README.md"
        else:
            items = [item for item in profile_documents(str(config["profile"])) if item.get("gate") in stages]
            records = []
            for item in items:
                relative = rendered_profile_path(item, values)
                path_value = docs / relative
                text = path_value.read_text(encoding="utf-8") if path_value.exists() and path_value.suffix == ".md" else ""
                meta = parse_frontmatter(text) if text else {}
                records.append(
                    {
                        "path": relative.as_posix(),
                        "exists": path_value.exists(),
                        "ready": meta.get("status") in (RELEASE_STATUSES if gate_id == "release" else READY_STATUSES),
                        "placeholder": bool(PLACEHOLDER_RE.search(text)),
                    }
                )
            total = len(records)
            ready = sum(1 for item in records if item["exists"] and item["ready"])
            placeholders = sum(1 for item in records if item["placeholder"])
            blockers = []
            if not total:
                blockers.append("当前 Profile 未定义该阶段文档")
            if any(not item["exists"] for item in records):
                blockers.append(f"{sum(1 for item in records if not item['exists'])} 份门禁文档缺失")
            if total - ready:
                blockers.append(f"{total - ready} 份门禁文档状态未就绪")
            if placeholders:
                blockers.append(f"{placeholders} 份门禁文档仍有待决占位")
            if gate_id == "version-ready" and unresolved_feature_adrs:
                blockers.append(f"{len(unresolved_feature_adrs)} 个功能依赖的 ADR 尚未接受")
            if gate_id == "version-ready" and approval["blocking_reason"]:
                blockers.append(approval["blocking_reason"])
            path = records[0]["path"] if records else ""
        status = "not_run" if not total else ("structure_ready" if not blockers else "blocked")
        gates.append(
            {
                "id": gate_id,
                "label": label,
                "status": status,
                "documents_total": total,
                "ready_documents": ready,
                "placeholder_documents": placeholders,
                "blocking_signals": blockers,
                "path": path,
            }
        )

    test_strategy_path = docs / "05-测试与发布/测试策略.md"
    test_strategy = test_strategy_path.read_text(encoding="utf-8") if test_strategy_path.exists() else ""
    current_digest = current_authority_digest or authority_digest(root, config)[0]
    evidence = browser_evidence(root, config, current_digest)
    evidence_by_type = {item["type"]: item for item in evidence}
    layers = [
        ("static", "静态检查", "静态检查", "development"),
        ("unit", "单元测试", "单元测试", "development"),
        ("integration", "集成/契约", "集成/契约", "development"),
        ("frontend", "前端测试", "前端测试", "development"),
        ("e2e", "E2E", "| E2E |", "e2e"),
        ("performance", "性能/容量", "性能/容量", "performance"),
        ("security-release", "安全/发布", "安全/发布", "release"),
    ]
    testing = [
        {
            "id": layer_id,
            "label": label,
            "defined": marker in test_strategy,
            "evidence_type": evidence_type,
            "evidence_result": evidence_by_type.get(evidence_type, {}).get("result", "not_run"),
        }
        for layer_id, label, marker, evidence_type in layers
    ]
    commits = {item["commit"] for item in evidence if item["result"] == "passed" and item["commit"]}
    builds = {item["build_id"] for item in evidence if item["result"] == "passed" and item["build_id"]}
    passed_evidence = [item for item in evidence if item["result"] == "passed"]
    return {
        "evaluation": "derived_structure",
        "notice": "结构信号用于发现缺口，不等于任何门禁已批准；passed 只来自实际机器证据。",
        "approval": approval,
        "change_sets": change_sets,
        "spec_drafts": spec_drafts,
        "gates": gates,
        "testing": testing,
        "design_depth": {
            "feature_total": len(features),
            "unit_contracts": sum(1 for item in features if item["has_unit_contract"]),
            "pseudocode": sum(1 for item in features if item["has_pseudocode"]),
            "stable_branches": sum(1 for item in features if item["branch_count"] > 0),
            "branch_trace": sum(1 for item in features if item["branch_trace_complete"]),
            "high_risk_total": sum(1 for item in features if item["risk"] == "high"),
            "high_risk_designs": sum(1 for item in features if item["risk"] == "high" and item["has_design"]),
        },
        "evidence": evidence,
        "evidence_binding": {
            "passed_reports": len(passed_evidence),
            "same_commit": len(passed_evidence) == len(EVIDENCE_TYPES) and len(commits) == 1,
            "same_build": len(passed_evidence) == len(EVIDENCE_TYPES) and len(builds) == 1,
            "fresh_reports": sum(1 for item in passed_evidence if item["freshness"] == "fresh"),
            "stale_reports": sum(1 for item in passed_evidence if item["freshness"] == "stale"),
        },
        "evidence_freshness": {
            "current_authority_digest": current_digest,
            "current_commit": git_head(root) or "",
            "fresh": sum(1 for item in passed_evidence if item["freshness"] == "fresh"),
            "stale": sum(1 for item in passed_evidence if item["freshness"] == "stale"),
            "unknown": sum(1 for item in evidence if item["freshness"] == "unknown"),
        },
    }


def snapshot_directory(root: Path, config: dict) -> Path:
    return docs_root(root, config) / "90-参考资料" / "版本快照"


def canonical_digest(value: object) -> str:
    payload = json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return f"sha256:{hashlib.sha256(payload.encode('utf-8')).hexdigest()}"


def snapshot_digest_for_documents(root: Path, config: dict, markers: tuple[str, ...]) -> str:
    docs = docs_root(root, config)
    selected: list[dict[str, str]] = []
    for path in authority_files(root, config):
        relative = path.relative_to(docs).as_posix()
        if any(marker in relative for marker in markers):
            selected.append({"path": relative, "digest": canonical_digest(path.read_text(encoding="utf-8"))})
    return canonical_digest(selected)


def snapshot_payload(root: Path, config: dict, commit: str | None = None) -> dict:
    """Create a complete immutable snapshot from the same derived workbench model."""
    payload = browser_payload(root, config)
    feature_rows = []
    acceptance_rows_snapshot = []
    for feature in payload["features"]:
        acceptance_ids_snapshot = []
        for item in feature.get("acceptance", []):
            acceptance_id = f"{feature['id']}:{item['id']}"
            acceptance_ids_snapshot.append(acceptance_id)
            acceptance_rows_snapshot.append(
                {
                    "id": acceptance_id,
                    "feature_id": feature["id"],
                    "acceptance_id": item["id"],
                    "test_layer": item.get("test_layer", ""),
                    "target_asset": item.get("target_asset", ""),
                    "command": item.get("command", ""),
                    "evidence": item.get("evidence", ""),
                    "semantic_digest": canonical_digest({key: item.get(key, "") for key in ["id", "given", "when", "then", "test_layer", "target_asset", "command", "evidence"]}),
                }
            )
        # 快照摘要必须覆盖所有会改变开发判断的功能语义。
        # 展示用字段也保留在摘要中，避免只改目标正文或分支说明却被误判为 unchanged。
        feature_semantic = {
            key: feature.get(key)
            for key in [
                "id",
                "title",
                "domain",
                "status",
                "risk",
                "risk_reason",
                "summary",
                "requirements",
                "decisions",
                "dependencies",
                "non_goals",
                "implementation_points",
                "forbidden_paths",
                "future_versions",
            ]
        }
        feature_semantic["branches"] = [
            {
                "id": branch.get("id", ""),
                "summary": branch.get("summary", ""),
                "acceptance_ids": branch.get("acceptance_ids", []),
            }
            for branch in feature.get("branches", [])
        ]
        feature_semantic["acceptance"] = acceptance_rows_snapshot[-len(acceptance_ids_snapshot):] if acceptance_ids_snapshot else []
        feature_rows.append(
            {
                "id": feature["id"],
                "title": feature["title"],
                "domain": feature.get("domain", ""),
                "status": feature.get("status", ""),
                "risk": feature.get("risk", ""),
                "risk_reason": feature.get("risk_reason", ""),
                "summary": feature.get("summary", ""),
                "requirements": feature.get("requirements", []),
                "decisions": feature.get("decisions", []),
                "dependencies": feature.get("dependencies", []),
                "acceptance_ids": acceptance_ids_snapshot,
                "branch_ids": [item["id"] for item in feature.get("branches", [])],
                "semantic_digest": canonical_digest(feature_semantic),
                "source_path": feature.get("path", ""),
            }
        )
    requirements = [
        {
            "id": item.get("id", ""),
            "type": item.get("type", ""),
            "title": item.get("title", ""),
            "status": item.get("status", ""),
            "semantic_digest": canonical_digest({key: item.get(key, "") for key in ["id", "type", "title", "status"]}),
            "source_path": item.get("source_path", ""),
        }
        for item in payload["requirements"]
    ]
    decisions = [
        {
            "id": item.get("id", ""),
            "title": item.get("title", ""),
            "status": item.get("status", ""),
            "decision": item.get("decision", ""),
            "rationale": item.get("rationale", ""),
            "semantic_digest": canonical_digest({key: item.get(key, "") for key in ["id", "title", "status", "decision", "rationale"]}),
            "source_path": item.get("source_path", ""),
        }
        for item in payload["decisions"]
    ]
    authority_digest_value, authority_count = authority_digest(root, config)
    source_commit = commit or git_head(root) or ""
    snapshot_id = f"SNAP-{config['current_version']}-{authority_digest_value.split(':', 1)[-1][:16]}"
    return {
        "schema_version": 1,
        "snapshot_id": snapshot_id,
        "immutable": True,
        "version": config["current_version"],
        "source_commit": source_commit,
        "authority_digest": authority_digest_value,
        "generated_at": now_iso(),
        "authority_file_count": authority_count,
        "features": feature_rows,
        "requirements": requirements,
        "acceptance": acceptance_rows_snapshot,
        "api_digest": snapshot_digest_for_documents(root, config, ("接口契约", "openapi")),
        "data_digest": snapshot_digest_for_documents(root, config, ("数据模型", "数据与事务", "数据边界")),
        "decisions": decisions,
    }


def browser_snapshots(root: Path, config: dict) -> list[dict]:
    directory = snapshot_directory(root, config)
    if not directory.exists():
        return []
    snapshots: list[dict] = []
    for path in sorted(directory.glob("*.json")):
        try:
            item = read_json(path, "版本快照")
        except DocsError:
            continue
        item = dict(item)
        item["path"] = path.relative_to(docs_root(root, config)).as_posix()
        item["feature_count"] = len(item.get("features", [])) if isinstance(item.get("features"), list) else 0
        item["requirement_count"] = len(item.get("requirements", [])) if isinstance(item.get("requirements"), list) else 0
        item["acceptance_count"] = len(item.get("acceptance", [])) if isinstance(item.get("acceptance"), list) else 0
        snapshots.append(item)
    return sorted(snapshots, key=lambda item: (str(item.get("version", "")), str(item.get("generated_at", "")), str(item.get("snapshot_id", ""))))


def browser_source(path: str, section: str, source_id: str = "", authority: str = "结构化权威表格") -> dict:
    return {
        "source_path": path,
        "source_section": section,
        "source_id": source_id,
        "authority": authority,
    }


def browser_structured_table(root: Path, config: dict, key: str) -> dict:
    contract = WORKBENCH_TABLE_CONTRACTS[key]
    relative = render(str(contract["path"]), values_for(config))
    path = docs_root(root, config) / relative
    result = {
        "key": key,
        "status": "unknown",
        "rows": [],
        "source_path": relative,
        "source_section": contract["section"],
        "headers": list(contract["headers"]),
        "actual_headers": [],
        "finding": "结构化来源未建立",
    }
    if not path.exists():
        result["finding"] = "权威文档不存在"
        return result
    section = markdown_section(path.read_text(encoding="utf-8"), str(contract["section"]))
    rows, actual_headers = markdown_table_rows_with_optional_headers(
        section, contract["headers"], contract.get("optional_headers", [])
    )
    if not section or not actual_headers:
        result["finding"] = "结构化表格缺失或列名不符合契约"
        return result
    row_is_meaningful = meaningful_evolution_relation_row if key == "evolution_relations" else meaningful_structured_row
    rows = [
        {header: clean_markdown_cell(value) for header, value in row.items()}
        for row in rows
        if row_is_meaningful(row)
    ]
    if not rows:
        result["finding"] = "结构化表格尚无完整数据行"
        return result
    result.update({"status": "ready", "rows": rows, "actual_headers": actual_headers, "finding": ""})
    return result


def derived_entity_id(prefix: str, value: str) -> str:
    digest = hashlib.sha256(value.encode("utf-8")).hexdigest()[:12].upper()
    return f"{prefix}-{digest}"


def map_entity_id(prefix: str, value: str) -> str:
    """Keep explicit stable IDs; derive an internal ID only for human labels."""
    normalized = clean_markdown_cell(value).strip()
    if re.fullmatch(r"[A-Z][A-Z0-9]*(?:-[A-Z0-9]+)+", normalized):
        return normalized
    return derived_entity_id(prefix, normalized)


def browser_map_views(
    root: Path,
    config: dict,
    documents: list[dict],
    directories: list[dict],
    features: list[dict],
    requirements: list[dict],
    decisions: list[dict],
    adrs: list[dict],
    e2e: list[dict],
    versions: list[dict],
    task_packets: list[dict],
    relations: list[dict],
) -> dict:
    tables = {key: browser_structured_table(root, config, key) for key in WORKBENCH_TABLE_CONTRACTS}

    def model(model_id: str, title: str) -> dict:
        return {"id": model_id, "title": title, "status": "unknown", "nodes": [], "edges": [], "findings": []}

    def add_node(
        target: dict,
        node_id: str,
        label: str,
        node_type: str,
        source: dict,
        detail: str = "",
        **attributes: object,
    ) -> None:
        if not node_id:
            return
        existing = next((item for item in target["nodes"] if item["id"] == node_id), None)
        if existing:
            if source not in existing["sources"]:
                existing["sources"].append(source)
            for key, value in attributes.items():
                if value not in (None, "", [], {}) and not existing.get(key):
                    existing[key] = value
            return
        node = {"id": node_id, "label": label or node_id, "type": node_type, "detail": detail, "sources": [source]}
        node.update({key: value for key, value in attributes.items() if value not in (None, "")})
        target["nodes"].append(node)

    def add_edge(target: dict, from_id: str, to_id: str, relation: str, label: str, source: dict) -> None:
        if not from_id or not to_id or from_id == to_id:
            return
        existing = next(
            (
                item
                for item in target["edges"]
                if item["from"] == from_id and item["to"] == to_id and item["relation"] == relation
            ),
            None,
        )
        if existing:
            if source not in existing["sources"]:
                existing["sources"].append(source)
            return
        target["edges"].append(
            {"from": from_id, "to": to_id, "relation": relation, "label": label or relation, "sources": [source]}
        )

    def finish(target: dict, table_keys: Iterable[str]) -> dict:
        target["nodes"] = sorted(target["nodes"], key=lambda item: item["id"])
        target["edges"] = sorted(target["edges"], key=lambda item: (item["from"], item["relation"], item["to"]))
        table_findings = [
            {
                "source_path": tables[key]["source_path"],
                "source_section": tables[key]["source_section"],
                "reason": tables[key]["finding"],
            }
            for key in table_keys
            if tables[key]["status"] != "ready"
        ]
        target["findings"] = target.get("findings", []) + table_findings
        incomplete_nodes = [item for item in target["nodes"] if incomplete(str(item.get("label", "")))]
        if incomplete_nodes:
            target["findings"].append(
                {
                    "source_path": (incomplete_nodes[0].get("sources") or [{}])[0].get("source_path", ""),
                    "source_section": (incomplete_nodes[0].get("sources") or [{}])[0].get("source_section", ""),
                    "reason": f"{len(incomplete_nodes)} 个节点仍包含待决占位",
                }
            )
        if not target["nodes"]:
            target["status"] = "unknown"
        elif target["findings"]:
            target["status"] = "blocked"
        else:
            target["status"] = "ready"
        return target

    component_rows = {row["组件 ID"]: row for row in tables["components"]["rows"]}

    product = model("product_architecture", "产品架构")
    for row in tables["product_information"]["rows"]:
        source = browser_source(tables["product_information"]["source_path"], tables["product_information"]["source_section"], row["稳定 ID"])
        domain_id = derived_entity_id("DOMAIN", row["所属领域"])
        add_node(product, row["稳定 ID"], row["用户/入口"], "user_entry", source, row["核心能力"])
        add_node(product, domain_id, row["所属领域"], "domain", source, row["目标结果"])
        add_edge(product, row["稳定 ID"], domain_id, "contains", row["核心能力"], source)
    for row in tables["components"]["rows"]:
        source = browser_source(tables["components"]["source_path"], tables["components"]["source_section"], row["组件 ID"])
        component_type = "external_system" if any(
            marker in row["类型"].lower() for marker in ["external", "third-party", "外部", "第三方"]
        ) else "component"
        add_node(
            product,
            row["组件 ID"],
            row["名称"],
            component_type,
            source,
            row["职责"],
            component_kind=row["类型"],
            deployment=row["部署单元"],
        )
        domain_id = derived_entity_id("DOMAIN", row["所属领域"])
        add_node(product, domain_id, row["所属领域"], "domain", source)
        add_edge(product, domain_id, row["组件 ID"], "contains", row["部署单元"], source)
    for row in tables["control_flow"]["rows"]:
        source = browser_source(tables["control_flow"]["source_path"], tables["control_flow"]["source_section"], row["关系 ID"])
        for component_id in [row["来源组件"], row["目标组件"]]:
            component = component_rows.get(component_id)
            if component:
                add_node(product, component_id, component["名称"], "component", source, component["职责"])
            else:
                add_node(product, component_id, component_id, "unmapped", source, "尚未在核心组件表登记")
                finding = {
                    "source_path": tables["control_flow"]["source_path"],
                    "source_section": tables["control_flow"]["source_section"],
                    "reason": f"关系 {row['关系 ID']} 引用未登记组件 {component_id}",
                }
                if finding not in product["findings"]:
                    product["findings"].append(finding)
        add_edge(product, row["来源组件"], row["目标组件"], row["关系"], row["契约"], source)
    finish(product, ["product_information", "components", "control_flow"])

    core_flow = model("core_flow", "核心流程")
    flow_rows = sorted(
        tables["core_flow"]["rows"],
        key=lambda row: (int(re.search(r"\d+", row["顺序"]).group()) if re.search(r"\d+", row["顺序"]) else 9999, row["步骤 ID"]),
    )
    previous_id = ""
    for row in flow_rows:
        source = browser_source(tables["core_flow"]["source_path"], tables["core_flow"]["source_section"], row["步骤 ID"])
        add_node(
            core_flow,
            row["步骤 ID"],
            row["动作"],
            "milestone",
            source,
            f"{row['参与者']} · 结果：{row['业务结果']} · 失败：{row['失败结果']}",
            order=row["顺序"],
            actor=row["参与者"],
            system=row["系统/领域"],
            outcome=row["业务结果"],
            failure=row["失败结果"],
        )
        if previous_id:
            add_edge(core_flow, previous_id, row["步骤 ID"], "precedes", row["系统/领域"], source)
        previous_id = row["步骤 ID"]
    finish(core_flow, ["core_flow"])

    roadmap = model("version_roadmap", "版本路线")
    roadmap_ids = {row["版本 ID"] for row in tables["version_sequence"]["rows"]}
    for index, row in enumerate(tables["version_sequence"]["rows"]):
        source = browser_source(tables["version_sequence"]["source_path"], tables["version_sequence"]["source_section"], row["版本 ID"])
        add_node(
            roadmap,
            row["版本 ID"],
            row["版本 ID"],
            "version",
            source,
            f"{row['目标']} · 退出：{row['退出条件']}",
            order=index,
            planning_status=row["状态"],
            goal=row["目标"],
            prerequisites=row["前置版本/能力"],
            exit_condition=row["退出条件"],
        )
        dependencies = [item for item in re.split(r"[,，、\s]+", row["前置版本/能力"]) if item in roadmap_ids]
        for dependency in dependencies:
            if dependency != row["版本 ID"]:
                add_edge(roadmap, dependency, row["版本 ID"], "unlocks", row["退出条件"], source)
    finish(roadmap, ["version_sequence"])

    data_domains = model("data_domains", "数据域")
    for row in tables["data_domains"]["rows"]:
        source = browser_source(tables["data_domains"]["source_path"], tables["data_domains"]["source_section"], row["数据域 ID"])
        writer_id = map_entity_id("OWNER", row["唯一写入者"])
        writer_label = component_rows.get(row["唯一写入者"], {}).get("名称", row["唯一写入者"])
        add_node(
            data_domains,
            row["数据域 ID"],
            row["数据/实体"],
            "data_domain",
            source,
            row["不变量"],
            invariant=row["不变量"],
        )
        add_node(data_domains, writer_id, writer_label, "component", source, role="唯一写入者")
        add_edge(data_domains, writer_id, row["数据域 ID"], "owns", row["关系"], source)
        for reader in [item.strip() for item in re.split(r"[,，、]", row["只读使用者"]) if item.strip()]:
            reader_id = map_entity_id("READER", reader)
            reader_label = component_rows.get(reader, {}).get("名称", reader)
            add_node(data_domains, reader_id, reader_label, "component", source, role="只读使用者")
            add_edge(data_domains, reader_id, row["数据域 ID"], "reads", "只读", source)
    finish(data_domains, ["data_domains"])

    labels: dict[str, tuple[str, str, dict]] = {}
    for item in documents:
        labels[item["path"]] = (item["title"], "document", browser_source(item["path"], "文档", item.get("stable_id", ""), item.get("authority", "文档")))
    for item in directories:
        labels[item["id"]] = (item["name"], "directory", browser_source(item.get("readme_path") or item["path"], "目录", item["id"], item.get("authority", "目录")))
    for items, item_type, label_field in [
        (requirements, "requirement", "title"),
        # FR 与功能共用稳定 ID；功能必须成为交付追踪的聚焦节点。
        (features, "feature", "title"),
        (decisions, "decision", "title"),
        (adrs, "adr", "title"),
        (e2e, "test", "title"),
        (versions, "version", "title"),
    ]:
        for item in items:
            item_id = str(item.get("id", ""))
            if item_id:
                source_section = "功能卡" if item_type == "feature" else "稳定 ID"
                labels[item_id] = (
                    str(item.get(label_field, item_id)),
                    item_type,
                    browser_source(str(item.get("source_path") or item.get("path") or ""), source_section, item_id),
                )
    feature_titles = {str(item.get("id", "")): str(item.get("title", "")) for item in features}
    for item in task_packets:
        item_id = str(item.get("id", ""))
        feature_id = str(item.get("feature_id", ""))
        if item_id:
            labels[item_id] = (
                f"{feature_titles.get(feature_id, feature_id)}开发任务包",
                "task",
                browser_source(str(item.get("source_path") or ""), str(item.get("source_section") or "实现与验证"), item_id),
            )
    for feature in features:
        feature_id = str(feature.get("id", ""))
        for acceptance in feature.get("acceptance", []):
            acceptance_id = f"{feature_id}:{acceptance.get('id', '')}"
            labels[acceptance_id] = (
                f"{acceptance.get('id', '')} {acceptance.get('then') or acceptance.get('when') or ''}".strip(),
                "acceptance",
                browser_source(feature.get("path", ""), "功能验收", acceptance_id),
            )
        for branch in feature.get("branches", []):
            labels[str(branch.get("id", ""))] = (
                str(branch.get("summary") or branch.get("id") or ""),
                "branch",
                browser_source(branch.get("source_path", feature.get("path", "")), branch.get("source_section", "稳定分支"), str(branch.get("id", ""))),
            )
    delivery = model("delivery_trace", "交付追踪")
    delivery_relations = {
        "satisfies", "has_acceptance", "traced_by", "verified_by", "depends_on",
        "decided_by", "implemented_by", "planned_for", "supersedes",
    }
    for relation in [item for item in relations if item.get("relation") in delivery_relations]:
        for entity_id in [relation["from"], relation["to"]]:
            label, entity_type, source = labels.get(entity_id, (entity_id, "entity", browser_source(relation.get("source_path", ""), relation.get("source_section", "关系"), entity_id)))
            add_node(delivery, entity_id, label, entity_type, source)
        source = (relation.get("sources") or [browser_source(relation.get("source_path", ""), relation.get("source_section", "关系"), relation["from"])])[0]
        add_edge(delivery, relation["from"], relation["to"], relation["relation"], relation.get("label", relation["relation"]), source)
    if not delivery["nodes"]:
        delivery["findings"] = [{"reason": "稳定 ID 追踪关系尚未建立", "source_path": "03-功能规格", "source_section": "需求追踪"}]
    finish(delivery, [])

    risks = model("risk_hotspots", "风险热区")
    for row in tables["risk_register"]["rows"]:
        source = browser_source(tables["risk_register"]["source_path"], tables["risk_register"]["source_section"], row["风险 ID"])
        target_id = derived_entity_id("RISK-TARGET", row["领域/对象"])
        control_id = derived_entity_id("CONTROL", f"{row['风险 ID']}:{row['控制']}")
        add_node(
            risks,
            row["风险 ID"],
            row["原因"],
            "risk",
            source,
            f"{row['等级']} · {row['影响']}",
            severity=row["等级"],
            risk_target=row["领域/对象"],
            impact=row["影响"],
            control=row["控制"],
            verification=row["验证入口"],
        )
        add_node(risks, target_id, row["领域/对象"], "domain", source, row["影响"])
        add_node(risks, control_id, row["控制"], "control", source, row["验证入口"], verification=row["验证入口"])
        add_edge(risks, row["风险 ID"], target_id, "affects", row["影响"], source)
        add_edge(risks, control_id, row["风险 ID"], "mitigates", row["验证入口"], source)
    finish(risks, ["risk_register"])

    return {
        "product_architecture": product,
        "core_flow": core_flow,
        "version_roadmap": roadmap,
        "data_domains": data_domains,
        "delivery_trace": delivery,
        "risk_hotspots": risks,
    }


def browser_change_summary(snapshots: list[dict]) -> dict:
    valid = [item for item in snapshots if item.get("immutable") is not False and item.get("snapshot_id")]
    valid.sort(key=lambda item: (str(item.get("generated_at", "")), str(item.get("snapshot_id", ""))))
    if len(valid) < 2:
        return {"available": False, "counts": {"added": 0, "changed": 0, "deprecated": 0, "removed": 0}, "items": []}
    baseline, current = valid[-2], valid[-1]
    items: list[dict] = []
    collections = [("feature", "features"), ("requirement", "requirements"), ("acceptance", "acceptance"), ("decision", "decisions")]
    for item_type, field in collections:
        before_items = baseline.get(field, []) if isinstance(baseline.get(field), list) else []
        after_items = current.get(field, []) if isinstance(current.get(field), list) else []

        def identity(item: dict) -> str:
            prefix = str(item.get("feature_id", ""))
            return f"{prefix}:{item.get('id', '')}" if prefix else str(item.get("id", ""))

        before = {identity(item): item for item in before_items if isinstance(item, dict) and identity(item)}
        after = {identity(item): item for item in after_items if isinstance(item, dict) and identity(item)}
        for object_id in sorted(set(before) | set(after)):
            previous = before.get(object_id)
            latest = after.get(object_id)
            if previous is None:
                change = "added"
            elif latest is None:
                change = "removed"
            elif latest.get("status") == "deprecated" and previous.get("status") != "deprecated":
                change = "deprecated"
            else:
                previous_digest = previous.get("semantic_digest") or hashlib.sha256(json.dumps(previous, ensure_ascii=False, sort_keys=True).encode("utf-8")).hexdigest()
                latest_digest = latest.get("semantic_digest") or hashlib.sha256(json.dumps(latest, ensure_ascii=False, sort_keys=True).encode("utf-8")).hexdigest()
                if previous_digest == latest_digest:
                    continue
                change = "changed"
            selected = latest or previous or {}
            impact = sorted(
                set(
                    [str(value) for value in selected.get("requirements", []) if value]
                    + [str(value) for value in selected.get("acceptance_ids", []) if value]
                )
            )
            summaries = {
                "added": "新增到权威快照",
                "changed": "权威语义发生变化",
                "deprecated": "对象已标记废弃",
                "removed": "对象已从当前快照删除",
            }
            items.append(
                {
                    "id": object_id,
                    "type": item_type,
                    "change": change,
                    "summary": summaries[change],
                    "impact": impact,
                    "source_path": str(selected.get("source_path") or selected.get("path") or ""),
                }
            )
    counts = {status: sum(1 for item in items if item["change"] == status) for status in ["added", "changed", "deprecated", "removed"]}
    return {
        "available": True,
        "baseline": {"version": baseline.get("version", ""), "authority_digest": baseline.get("authority_digest", "")},
        "current": {"version": current.get("version", ""), "authority_digest": current.get("authority_digest", "")},
        "counts": counts,
        "items": items,
        "details": {"source_commit": current.get("source_commit", ""), "generated_at": current.get("generated_at", "")},
    }


def evolution_planning_status(value: str) -> str:
    # The status column may cite a source after a semicolon.  Parse only its
    # leading status token so prose such as "未完成任务" cannot become completed.
    normalized = re.split(r"[；;，,]", value.lower(), maxsplit=1)[0].strip()
    if any(word in normalized for word in ["基线", "baseline"]):
        return "baseline"
    if any(word in normalized for word in ["当前执行", "active"]):
        return "active"
    if any(word in normalized for word in ["废弃", "deprecated"]):
        return "deprecated"
    if any(word in normalized for word in ["已完成", "已发布", "已验证", "released", "verified"]):
        return "completed"
    if any(word in normalized for word in ["当前", "current", "实现"]):
        return "current"
    return "planning"


def evolution_relation_type(value: str) -> str:
    normalized = value.strip().lower()
    if normalized in {"none", "无", "无关系", "不适用"}:
        return "none"
    if any(word in normalized for word in ["兼容", "compatible"]):
        return "compatible"
    if any(word in normalized for word in ["迁移", "migration", "migrate"]):
        return "migration"
    if any(word in normalized for word in ["废弃", "deprecation", "deprecated"]):
        return "deprecation"
    if any(word in normalized for word in ["替代", "replacement", "replace", "supersede"]):
        return "replacement"
    return "unknown"


def browser_evolution_view(root: Path, config: dict) -> dict:
    version_table = browser_structured_table(root, config, "version_sequence")
    evolution_table = browser_structured_table(root, config, "evolution")
    relation_table = browser_structured_table(root, config, "evolution_relations")
    findings = [
        {"source_path": table["source_path"], "source_section": table["source_section"], "reason": table["finding"]}
        for table in [version_table, evolution_table, relation_table]
        if table["status"] != "ready"
    ]

    versions = []
    version_ids: list[str] = []
    for order, row in enumerate(version_table["rows"]):
        version_id = row["版本 ID"]
        if version_id in version_ids:
            findings.append(
                {
                    "source_path": version_table["source_path"],
                    "source_section": version_table["source_section"],
                    "reason": f"版本 ID 重复：{version_id}",
                }
            )
            continue
        version_ids.append(version_id)
        versions.append(
            {
                "id": version_id,
                "goal": row["目标"],
                "status": row["状态"],
                "prerequisites": row["前置版本/能力"],
                "exit_condition": row["退出条件"],
                "order": order,
                "sources": [
                    browser_source(
                        version_table["source_path"], version_table["source_section"], version_id
                    )
                ],
            }
        )

    def stage_version_ids(value: str) -> list[str]:
        matches = []
        for version_id in version_ids:
            pattern = rf"(?<![A-Z0-9]){re.escape(version_id)}(?![A-Z0-9])"
            if re.search(pattern, value, flags=re.IGNORECASE):
                matches.append(version_id)
        return matches

    tracks: dict[str, dict] = {}
    milestones: list[dict] = []
    milestone_ids: set[str] = set()
    extra_stages: dict[str, dict] = {}
    for source_order, row in enumerate(evolution_table["rows"]):
        milestone_id = row["里程碑 ID"]
        track_match = re.search(r"\bTRACK-[A-Z0-9][A-Z0-9-]*\b", row["能力主线"].upper())
        if not track_match:
            findings.append(
                {
                    "source_path": evolution_table["source_path"],
                    "source_section": evolution_table["source_section"],
                    "reason": f"里程碑 {milestone_id or '未编号'} 缺少 TRACK-* 能力主线 ID",
                }
            )
            continue
        if not re.fullmatch(r"MS-[A-Z0-9][A-Z0-9-]*", milestone_id.upper()):
            findings.append(
                {
                    "source_path": evolution_table["source_path"],
                    "source_section": evolution_table["source_section"],
                    "reason": f"里程碑 ID 无效：{milestone_id}",
                }
            )
            continue
        milestone_id = milestone_id.upper()
        if milestone_id in milestone_ids:
            findings.append(
                {
                    "source_path": evolution_table["source_path"],
                    "source_section": evolution_table["source_section"],
                    "reason": f"里程碑 ID 重复：{milestone_id}",
                }
            )
            continue
        milestone_ids.add(milestone_id)
        track_id = track_match.group(0)
        track_title = re.sub(re.escape(track_id), "", row["能力主线"], flags=re.IGNORECASE).strip(" ·-—")
        if not track_title:
            track_title = track_id
            findings.append(
                {
                    "source_path": evolution_table["source_path"],
                    "source_section": evolution_table["source_section"],
                    "reason": f"能力主线 {track_id} 缺少面向开发者的业务名称",
                }
            )
        source = browser_source(
            evolution_table["source_path"], evolution_table["source_section"], milestone_id
        )
        raw_stage = row["版本/阶段"]
        matched_versions = stage_version_ids(raw_stage)
        if matched_versions:
            stage_keys = matched_versions
        else:
            stage_key = f"stage:{raw_stage}"
            stage_keys = [stage_key]
            extra_stages.setdefault(
                stage_key,
                {
                    "id": stage_key,
                    "label": raw_stage,
                    "kind": "stage",
                    "order": len(version_ids) + len(extra_stages),
                    "sources": [source],
                },
            )
        milestones.append(
            {
                "id": milestone_id,
                "track_id": track_id,
                "version": raw_stage,
                "version_ids": matched_versions,
                "stage_keys": stage_keys,
                "user_change": row["用户可感知变化"],
                "dependencies": [
                    item.strip() for item in re.split(r"[,，、]", row["依赖与边界"]) if item.strip()
                ],
                "completion": row["完成判定"],
                "planning_status": evolution_planning_status(row["状态与来源"]),
                "order": source_order,
                "sources": [source],
            }
        )
        track = tracks.setdefault(
            track_id,
            {"id": track_id, "title": track_title, "order": len(tracks), "milestone_ids": []},
        )
        if track["title"] == track_id and track_title != track_id:
            track["title"] = track_title
        track["milestone_ids"].append(milestone_id)

    known_endpoints = {item["id"] for item in versions} | milestone_ids
    endpoint_names = {value.upper(): value for value in known_endpoints}

    def endpoint(value: str) -> str:
        normalized = value.strip()
        if normalized.lower() in {"", "none", "无", "-", "不适用"}:
            return ""
        return endpoint_names.get(normalized.upper(), normalized)

    relationships = []
    relation_ids: set[str] = set()
    for order, row in enumerate(relation_table["rows"]):
        relation_id = row["关系 ID"].upper()
        relation_type = evolution_relation_type(row["关系类型"])
        if relation_type == "none":
            continue
        source_id = endpoint(row["来源版本/里程碑"])
        target_id = endpoint(row["目标版本/里程碑"])
        relation_source = browser_source(
            relation_table["source_path"], relation_table["source_section"], relation_id
        )
        if not re.fullmatch(r"ER-[A-Z0-9][A-Z0-9-]*", relation_id):
            findings.append(
                {
                    "source_path": relation_table["source_path"],
                    "source_section": relation_table["source_section"],
                    "reason": f"演进关系 ID 无效：{relation_id}",
                }
            )
            continue
        if relation_id in relation_ids:
            findings.append(
                {
                    "source_path": relation_table["source_path"],
                    "source_section": relation_table["source_section"],
                    "reason": f"演进关系 ID 重复：{relation_id}",
                }
            )
            continue
        relation_ids.add(relation_id)
        if relation_type == "unknown":
            findings.append(
                {
                    "source_path": relation_table["source_path"],
                    "source_section": relation_table["source_section"],
                    "reason": f"演进关系类型无效：{row['关系类型']}",
                }
            )
        if source_id not in known_endpoints:
            findings.append(
                {
                    "source_path": relation_table["source_path"],
                    "source_section": relation_table["source_section"],
                    "reason": f"演进关系引用未知来源对象：{relation_id} -> {source_id or '未登记'}",
                }
            )
        if target_id and target_id not in known_endpoints:
            findings.append(
                {
                    "source_path": relation_table["source_path"],
                    "source_section": relation_table["source_section"],
                    "reason": f"演进关系引用未知目标对象：{relation_id} -> {target_id}",
                }
            )
        if relation_type != "deprecation" and not target_id:
            findings.append(
                {
                    "source_path": relation_table["source_path"],
                    "source_section": relation_table["source_section"],
                    "reason": f"演进关系缺少目标对象：{relation_id}",
                }
            )
        relationships.append(
            {
                "id": relation_id,
                "type": relation_type,
                "from": source_id,
                "to": target_id,
                "impact": row["影响与处理"],
                "planning_status": evolution_planning_status(row["状态与来源"]),
                "order": order,
                "sources": [relation_source],
            }
        )

    stages = [
        {
            "id": item["id"],
            "label": item["id"],
            "kind": "version",
            "order": item["order"],
            "status": item["status"],
            "sources": item["sources"],
        }
        for item in versions
    ] + list(extra_stages.values())
    stage_order = {item["id"]: item["order"] for item in stages}
    track_order = {item["id"]: item["order"] for item in tracks.values()}
    milestones.sort(
        key=lambda item: (
            min((stage_order.get(key, len(stages)) for key in item["stage_keys"]), default=len(stages)),
            track_order.get(item["track_id"], len(tracks)),
            item["order"],
        )
    )
    relationships.sort(key=lambda item: item["order"])
    if not versions and not milestones:
        status = "unknown"
    elif findings:
        status = "blocked"
    else:
        status = "ready"
    return {
        "status": status,
        "versions": versions,
        "stages": stages,
        "tracks": sorted(tracks.values(), key=lambda item: item["order"]),
        "milestones": milestones,
        "relationships": relationships,
        "findings": findings,
    }


def browser_workbench_view(
    config: dict,
    feature: dict | None,
    findings: list[dict],
    task_packets: list[dict],
    governance: dict,
) -> dict:
    feature_id = str(feature.get("id", "")) if feature else ""
    relevant = workbench_development_findings(findings, feature_id)
    severity_order = {"blocking": 0, "high": 1, "medium": 2, "info": 3}
    relevant.sort(key=lambda item: (severity_order.get(item.get("severity", "info"), 9), item.get("id", "")))
    packet = next((item for item in task_packets if item.get("feature_id") == feature_id), None)
    blockers = [item for item in relevant if item.get("severity") in {"blocking", "high"}]
    if blockers:
        decision = {"status": "blocked", "reason": blockers[0].get("reason", "存在开发阻塞")}
        next_action = {
            "label": blockers[0].get("recovery_action", "处理首要阻塞"),
            "finding_id": blockers[0].get("id", ""),
            "source_path": blockers[0].get("source_path", ""),
            "source_section": blockers[0].get("source_section", ""),
        }
    elif packet and packet.get("status") == "ready":
        decision = {"status": "ready", "reason": "当前功能结构就绪，仍需执行正式 Feature Ready gate。"}
        next_action = {"label": "复制开发任务包", "task_packet_id": packet["id"]}
    else:
        decision = {"status": "unknown", "reason": "尚无足够信息判断是否允许开发。"}
        next_action = {"label": "完成当前功能规格与门禁检查"}
    implementation_status = "unknown"
    if feature:
        if feature.get("status") in {"planning", "draft"}:
            implementation_status = "not_started"
        elif feature.get("status") == "implementing":
            implementation_status = "implementing"
        elif feature.get("status") in {"local_verified", "staging_verified", "released"}:
            implementation_status = "implemented"
    development_evidence = next((item for item in governance.get("evidence", []) if item.get("type") == "development"), {})
    verification_status = development_evidence.get("result", "not_run")
    if verification_status == "passed" and development_evidence.get("freshness") != "fresh":
        verification_status = "stale"
    return {
        "context": {
            "version": config["current_version"],
            "feature_id": feature_id,
            "stage": next(
                (item.get("stage") for item in relevant if item.get("stage") in DEVELOPMENT_WORKBENCH_STAGES),
                "feature-ready" if feature else "discovery",
            ),
        },
        "decision": decision,
        "next_action": next_action,
        "top_blockers": [item["id"] for item in blockers[:3]],
        "blocker_total": len(blockers),
        "progress": {
            "specification": "ready" if feature and feature.get("status") in READY_STATUSES and not feature.get("has_placeholders") else "blocked",
            "design": "ready" if feature and feature.get("design_structure_complete") else "blocked",
            "implementation": implementation_status,
            "verification": verification_status,
        },
        "task_packet_id": packet.get("id", "") if packet else "",
        "verification_summary": governance.get("evidence_binding", {}),
    }


def portfolio_feature_summary(root: Path, config: dict, record: dict, version: str) -> dict:
    """Build a browsing-only feature summary without entering execution inputs.

    This deliberately does not create task packets, findings, gate conclusions,
    or Goal data for non-active versions.  Those objects are governed by the
    active execution version only.
    """
    meta = record["meta"]
    status = str(meta.get("status", "draft"))
    is_active_version = version == str(config["current_version"])
    signal = feature_implementation_signal(root, record) if is_active_version else {}
    points = sum(len(items) for items in (signal.get("paths") or {}).values())
    existing = sum(len(items) for items in (signal.get("existing_paths") or {}).values())
    if not is_active_version:
        implementation = "unknown"
        implementation_basis = "历史版本未登记独立机器证据或冻结工程快照，当前实现状态待确认。"
    elif status in {"released", "staging_verified", "local_verified"}:
        implementation = status
        implementation_basis = f"功能状态为 {status}；仍需单独查看对应机器证据。"
    elif status == "implementing" or existing:
        implementation = "implementing"
        implementation_basis = f"检测到 {existing} 个已存在工程落点；尚未据此推断验证或发布。"
    elif status in {"planning", "draft", "ready"} or points:
        implementation = "not_started"
        implementation_basis = f"已声明 {points} 个工程落点，当前未检测到实现落点。"
    else:
        implementation = "unknown"
        implementation_basis = "功能状态和工程落点不足以判断实现进度。"
    return {
        "id": str(meta.get("id", "")),
        "number": record["number"],
        "title": record["title"],
        "version": version,
        "status": status,
        "domain": str(meta.get("domain", "未分类")),
        "risk": str(meta.get("risk", "standard")),
        "evolution_track": str(meta.get("evolution_track", "none")),
        "dependencies": list_field(meta.get("dependencies", "")),
        "path": record["path"].relative_to(docs_root(root, config)).as_posix(),
        "summary": browser_excerpt(record["text"], "目标") or browser_excerpt(record["text"]),
        "specification": "ready" if status in READY_STATUSES and not PLACEHOLDER_RE.search(record["text"]) else "blocked",
        "implementation": implementation,
        "implementation_basis": implementation_basis,
        "implementation_signal": signal,
        # Cross-version evidence is never inferred from the active evidence
        # selector.  A project may retain only a historical specification.
        "verification": "unknown",
        "delivery": delivery_target_summary(root, config, str(meta.get("id", "")), version) if is_active_version and meta.get("id") else {"state": "unknown", "basis": "历史版本没有独立交付登记。", "goal_links": [], "records": []},
        "sources": [
            browser_source(
                record["path"].relative_to(docs_root(root, config)).as_posix(),
                "功能规格",
                str(meta.get("id", "")),
                "功能行为、工程落点与验收",
            )
        ],
    }


def browser_project_features(
    root: Path,
    config: dict,
    portfolio: dict,
    active_features: list[dict],
) -> list[dict]:
    """Build the project-wide browsing catalog without widening execution scope.

    ``features`` remains the authoritative active-version execution input.  This
    catalog is deliberately separate so a reader can choose a historical feature
    in search or a timeline without introducing its findings, evidence, task
    packet, or Goal eligibility into the active version.
    """
    active_by_id = {str(item.get("id", "")): item for item in active_features if item.get("id")}
    versions = portfolio.get("versions") or []
    order_by_version = {str(item.get("id", "")): index for index, item in enumerate(versions)}
    version_ids = [version for version in order_by_version if version]
    feature_root = docs_root(root, config) / "03-功能规格"
    if feature_root.exists():
        for path in sorted(feature_root.iterdir()):
            if path.is_dir() and re.fullmatch(r"V\d+", path.name, re.IGNORECASE):
                version_id = path.name.upper()
                if version_id not in order_by_version:
                    order_by_version[version_id] = len(order_by_version)
                    version_ids.append(version_id)

    catalog: list[dict] = []
    seen_ids: set[str] = set()
    for version_id in version_ids:
        for record in feature_documents(root, config, version_id):
            summary = portfolio_feature_summary(root, config, record, version_id)
            feature_id = str(summary.get("id", ""))
            if not feature_id or feature_id in seen_ids:
                continue
            seen_ids.add(feature_id)
            # Active-version details can enrich browsing, but must not alter the
            # historical summaries or create execution objects for them.
            if version_id == str(config["current_version"]) and feature_id in active_by_id:
                summary = {**summary, **active_by_id[feature_id], "version": version_id}
            catalog.append(summary)
    return sorted(
        catalog,
        key=lambda item: (
            order_by_version.get(str(item.get("version", "")), len(order_by_version)),
            int(item.get("number", 0) or 0),
            str(item.get("id", "")),
        ),
    )


def browser_version_portfolio(root: Path, config: dict, documents: list[dict]) -> dict:
    """Derive the project-wide browsing portfolio from registered version facts."""
    table = browser_structured_table(root, config, "version_sequence")
    rows = table["rows"] if table["status"] == "ready" else []
    cards: list[dict] = []
    seen: set[str] = set()
    for order, row in enumerate(rows):
        version_id = str(row.get("版本 ID", "")).upper()
        if not version_id or version_id in seen:
            continue
        seen.add(version_id)
        features = [
            portfolio_feature_summary(root, config, record, version_id)
            for record in feature_documents(root, config, version_id)
        ]
        specification = (
            "ready" if features and all(item["specification"] == "ready" for item in features)
            else "blocked" if features
            else "unknown"
        )
        implementation_values = {item["implementation"] for item in features}
        if not features:
            implementation = "unknown"
        elif implementation_values <= {"not_started"}:
            implementation = "not_started"
        elif any(value in {"implementing", "local_verified", "staging_verified", "released"} for value in implementation_values):
            implementation = "implementing"
        else:
            implementation = "unknown"
        overview = next(
            (
                document
                for document in documents
                if document.get("version") == version_id and document.get("path", "").endswith(f"{version_id}-版本总览.md")
            ),
            None,
        )
        source = browser_source(
            table["source_path"], table["source_section"], version_id, "版本目标、先后依赖和退出条件"
        )
        sources = [source]
        if overview:
            sources.append(browser_source(overview["path"], "版本总览", version_id, overview.get("authority", "版本边界")))
        cards.append(
            {
                "id": version_id,
                "order": order,
                "role": str(row.get("版本角色", "unknown")).strip().lower() or "unknown",
                "goal": row.get("目标", ""),
                "planning_status": row.get("状态", "unknown"),
                "prerequisites": row.get("前置版本/能力", ""),
                "exit_condition": row.get("退出条件", ""),
                "overview_path": overview.get("path", "") if overview else "",
                "feature_count": len(features),
                "features": features,
                "delivery": {
                    "specification": specification,
                    "implementation": implementation,
                    "verification": "unknown",
                },
                "sources": sources,
            }
        )
    if str(config["current_version"]) not in seen:
        cards.append(
            {
                "id": str(config["current_version"]),
                "order": len(cards),
                "role": "active",
                "goal": "",
                "planning_status": "unknown",
                "prerequisites": "",
                "exit_condition": "",
                "overview_path": "",
                "feature_count": 0,
                "features": [],
                "delivery": {"specification": "unknown", "implementation": "unknown", "verification": "unknown"},
                "sources": [
                    browser_source(
                        table["source_path"],
                        table["source_section"],
                        str(config["current_version"]),
                        "版本注册表尚未形成有效行",
                    )
                ],
            }
        )
        seen.add(str(config["current_version"]))

    # A formal future plan is useful before the roadmap has been frozen.  It is
    # shown as an isolated planning card, never as active execution scope or
    # implementation evidence.  Once the roadmap registers the same version,
    # the plan enriches that card instead of duplicating version facts.
    cards_by_id = {str(item.get("id", "")): item for item in cards}
    for plan in future_version_plan_records(root, config):
        version_id = str(plan["version"])
        relative = plan["path"].relative_to(docs_root(root, config)).as_posix()
        source = browser_source(relative, "版本总览", version_id, f"{version_id} 后续版本规划入口")
        existing = cards_by_id.get(version_id)
        if existing:
            if not existing.get("overview_path"):
                existing["overview_path"] = relative
            if not existing.get("goal"):
                existing["goal"] = str(plan["title"])
            if existing.get("planning_status") in {"", "unknown"}:
                existing["planning_status"] = str(plan["status"])
            if source not in existing.get("sources", []):
                existing.setdefault("sources", []).append(source)
            continue
        card = {
            "id": version_id,
            "order": len(cards),
            "role": "future",
            "goal": str(plan["title"]),
            "planning_status": str(plan["status"]),
            "prerequisites": "未在版本路线图登记",
            "exit_condition": "未在版本路线图登记",
            "overview_path": relative,
            "feature_count": 0,
            "features": [],
            "delivery": {"specification": "unknown", "implementation": "unknown", "verification": "unknown"},
            "sources": [source],
        }
        cards.append(card)
        cards_by_id[version_id] = card
    return {
        "status": "ready" if cards and table["status"] == "ready" else "unknown",
        "active_execution_version": str(config["current_version"]),
        "browsing_scopes": [{"id": "all", "label": "全部版本"}] + [
            {"id": item["id"], "label": item["id"]} for item in cards
        ],
        "versions": cards,
        "findings": [] if cards else [{"reason": table["finding"], "source_path": table["source_path"], "source_section": table["source_section"]}],
    }


def browser_reader_navigation(documents: list[dict], portfolio: dict) -> dict:
    """Provide semantic document groups while retaining the physical directory tree."""
    version_ids = [str(item.get("id", "")) for item in portfolio.get("versions", []) if item.get("id")]
    global_docs = sorted(
        [document["path"] for document in documents if not document.get("version")], key=str
    )
    version_groups = [
        {
            "id": "global",
            "label": "项目全局",
            "document_paths": global_docs,
        }
    ]
    project_groups = [dict(version_groups[0])]
    for version_id in version_ids:
        scoped = sorted([document["path"] for document in documents if document.get("version") == version_id], key=str)
        overview = next((path for path in scoped if path.endswith(f"{version_id}-版本总览.md")), "")
        version_groups.append({"id": version_id, "label": version_id, "document_paths": scoped})
        project_groups.append(
            {"id": f"entry-{version_id}", "label": f"{version_id} 版本入口", "document_paths": [overview] if overview else []}
        )
    return {
        "modes": [
            {"id": "project", "label": "项目视角", "groups": project_groups},
            {"id": "version", "label": "按版本", "groups": version_groups},
            {"id": "path", "label": "原始目录", "groups": []},
        ]
    }


def browser_goal_readiness(task_packets: list[dict], findings: list[dict], authority_digest_value: str) -> dict:
    blocked = [item for item in task_packets if item.get("status") != "ready"]
    blocking_ids = [
        item["id"]
        for item in findings
        if item.get("status") == "open"
        and item.get("stage") in DEVELOPMENT_WORKBENCH_STAGES
        and item.get("severity") in {"blocking", "high"}
    ]
    return {
        "status": "ready" if task_packets and not blocked else "blocked",
        "reason": "全部功能任务包结构就绪" if task_packets and not blocked else f"{len(blocked)} 个功能尚未达到 Goal 就绪条件",
        "feature_ids": [item.get("feature_id", "") for item in task_packets],
        "blocking_finding_ids": blocking_ids,
        "authority_digest": authority_digest_value,
    }


def browser_goal_runtime(root: Path, config: dict) -> list[dict]:
    """Expose read-only runtime summaries for Goals in the developer workbench."""
    goals_root = root / ".daoge-docs" / "goals"
    if not goals_root.is_dir():
        return []
    summaries: list[dict] = []
    for directory in sorted(goals_root.iterdir(), key=lambda path: path.name):
        manifest_path = directory / "goal-manifest.json"
        if not manifest_path.is_file():
            continue
        goal_id = directory.name
        try:
            _, manifest = load_goal_manifest(root, goal_id)
            target_config = goal_target_config(config, str(manifest.get("version", "")))
            records, expected_commit = validate_goal_checkpoint_chain(root, manifest)
            completion = validate_goal_completion(root, manifest)
            reasons = []
            freshness = []
            authority_scope = manifest.get("authority_scope") if isinstance(manifest.get("authority_scope"), dict) else {}
            current_digest = (
                goal_authority_digest(root, target_config, authority_scope)[0]
                if authority_scope
                else authority_digest(root, target_config)[0]
            )
            if completion:
                status = "completed"
                if manifest.get("authority_digest") != current_digest:
                    freshness.append("当前权威已变化，完成记录作为历史证据保留")
            else:
                reasons = goal_execution_reasons(root, config, manifest, expected_commit)
                status = "stale" if reasons else ("blocked" if manifest.get("blocking_findings") else str(manifest.get("status", "ready")))
            runtime_manifest = dict(manifest)
            runtime_manifest["status"] = status
            execution = goal_execution_snapshot(runtime_manifest)
            summaries.append({
                "goal_id": goal_id,
                "status": status,
                "version": manifest.get("version", ""),
                "feature_ids": manifest.get("feature_ids", []),
                "current_execution_version": config.get("current_version", ""),
                "actionable_task_ids": execution["actionable_task_ids"] if status in {"ready", "running", "verification_failed"} else [],
                "execution": execution,
                "checkpoint_count": len(records),
                "stale_reasons": reasons,
                "historical_reasons": freshness,
                "source_commit": manifest.get("source_commit", ""),
                "authority_digest": manifest.get("authority_digest", ""),
                "path": str(manifest_path.relative_to(root)),
            })
        except (DocsError, OSError, ValueError) as exc:
            summaries.append({
                "goal_id": goal_id,
                "status": "unknown",
                "version": "",
                "feature_ids": [],
                "current_execution_version": config.get("current_version", ""),
                "actionable_task_ids": [],
                "execution": {"task_count": 0, "tasks": [], "lanes": [], "notice": "Goal 清单无法验证。"},
                "checkpoint_count": 0,
                "stale_reasons": [f"Goal 清单无法验证：{exc}"],
                "historical_reasons": [],
                "source_commit": "",
                "authority_digest": "",
                "path": str(manifest_path.relative_to(root)),
            })
    return summaries


def browser_payload(root: Path, config: dict) -> dict:
    docs = docs_root(root, config)
    generation_stamp = f"{today()}T00:00:00Z"
    authority_digest_value, authority_file_count = authority_digest(root, config)
    source_commit = git_head(root)
    documents = browser_records(root, config)
    directories = browser_directories(root, config, documents)
    version_portfolio = browser_version_portfolio(root, config, documents)
    reader_navigation = browser_reader_navigation(documents, version_portfolio)
    future_versions = []
    for path in future_version_documents(root, config):
        text = path.read_text(encoding="utf-8")
        meta = parse_frontmatter(text)
        future_versions.append(
            {
                "id": meta.get("version", path.name.split("-", 1)[0]),
                "title": markdown_title(text),
                "status": meta.get("status", "planning"),
                "updated": meta.get("updated", "未声明"),
                "path": path.relative_to(docs).as_posix(),
                "summary": browser_excerpt(text, "版本定位") or browser_excerpt(text),
                "content": text,
            }
        )
    features = []
    for record in feature_documents(root, config):
        meta = record["meta"]
        rows = acceptance_rows(record["text"])
        design_path = record["path"].with_name(record["path"].stem + "-技术设计.md")
        design_text = design_path.read_text(encoding="utf-8") if meta.get("risk") == "high" and design_path.exists() else record["text"]
        depth = design_depth(design_text, high_risk=meta.get("risk") == "high")
        feature_acceptance = set(acceptance_ids(record["text"]))
        acceptance = []
        for row in rows:
            acceptance.append(
                {
                    "id": row[0] if row else "未知 AC",
                    "given": row[1] if len(row) > 1 else "",
                    "when": row[2] if len(row) > 2 else "",
                    "then": row[3] if len(row) > 3 else "",
                    "test_layer": row[4] if len(row) > 4 else "",
                    "target_asset": row[5] if len(row) > 5 else "",
                    # The source table is Markdown and commonly wraps commands in
                    # inline code. Goal verification must receive a shell command,
                    # not Markdown backticks that become command substitution.
                    "command": clean_markdown_cell(row[6]) if len(row) > 6 else "",
                    "evidence": row[7] if len(row) > 7 else "",
                    "source_path": record["path"].relative_to(docs).as_posix(),
                    "source_section": "功能验收",
                }
            )
        branch_ids = design_branch_ids(design_text)
        branches = []
        for branch_id in branch_ids:
            branch_line = next((line.strip() for line in design_text.splitlines() if branch_id in line), branch_id)
            branches.append(
                {
                    "id": branch_id,
                    "summary": re.sub(r"^\|\s*[^|]+\|\s*", "", branch_line).strip(" |"),
                    "acceptance_ids": sorted(set(re.findall(r"\bAC\d{2,}\b", branch_line))),
                    "source_path": record["path"].with_name(record["path"].stem + "-技术设计.md").relative_to(docs).as_posix() if meta.get("risk") == "high" and design_path.exists() else record["path"].relative_to(docs).as_posix(),
                    "source_section": "状态机与稳定分支",
                }
            )
        implementation_points = implementation_points_from_text(record["text"])
        implementation_signal = feature_implementation_signal(root, record)
        non_goals = []
        non_goal_section = markdown_section(record["text"], f"{config['current_version']} 不做")
        if non_goal_section:
            non_goals = [
                re.sub(r"^[-*]\s+", "", line).strip()
                for line in non_goal_section.splitlines()[1:]
                if re.match(r"^\s*[-*]\s+", line) and line.strip()
            ]
        features.append(
            {
                "id": meta.get("id", ""),
                "number": record["number"],
                "title": record["title"],
                "domain": meta.get("domain", "未分类"),
                "evolution_track": meta.get("evolution_track", "none"),
                "status": meta.get("status", "draft"),
                "risk": meta.get("risk", "standard"),
                "risk_reason": meta.get("risk_reason", "未填写"),
                "owner": meta.get("owner", "未声明"),
                "updated": meta.get("updated", "未声明"),
                "path": record["path"].relative_to(docs).as_posix(),
                "design_path": design_path.relative_to(docs).as_posix() if design_path.exists() else "",
                "summary": browser_excerpt(record["text"], "目标") or browser_excerpt(record["text"]),
                "requirements": list_field(meta.get("requirements", "")),
                "decisions": list_field(meta.get("decisions", "")),
                "dependencies": list_field(meta.get("dependencies", "")),
                "forbidden_paths": normalize_goal_paths(meta.get("forbidden_paths", "")),
                "acceptance_total": len(rows),
                "acceptance_evidenced": sum(1 for row in rows if len(row) >= 8 and not incomplete(row[7])),
                "acceptance": acceptance,
                "branches": branches,
                "implementation_points": implementation_points,
                "implementation_signal": implementation_signal,
                "delivery": delivery_target_summary(root, config, str(meta.get("id", "")), str(config["current_version"])) if meta.get("id") else {"state": "unknown", "basis": "功能没有稳定 ID。", "goal_links": [], "records": []},
                "non_goals": non_goals,
                "has_design": design_path.exists(),
                "has_unit_contract": not bool(missing_headings(design_text, ["函数/用例签名"] if meta.get("risk") == "high" else ["单元契约"])),
                "has_pseudocode": depth["pseudocode_executable"],
                "branch_count": len(depth["branch_ids"]),
                "branch_trace_complete": bool(depth["trace_branch_ids"]) and feature_acceptance.issubset(set(depth["trace_acceptance_ids"])),
                "design_structure_complete": (
                    not depth["missing_sections"]
                    and depth["pseudocode_executable"]
                    and len(depth["branch_ids"]) >= (2 if meta.get("risk") == "high" else 1)
                    and bool(depth["trace_branch_ids"])
                    and feature_acceptance.issubset(set(depth["trace_acceptance_ids"]))
                ),
                "has_placeholders": bool(PLACEHOLDER_RE.search(record["text"])) or (meta.get("risk") == "high" and bool(PLACEHOLDER_RE.search(design_text))),
                "future_versions": [],
            }
        )
    requirements = [
        {
            "id": item.get("id", ""),
            "type": item.get("type", "未知"),
            "title": item.get("title", "未填写"),
            "status": item.get("status", "draft"),
            "source_path": source_path,
            "source_label": source_label,
            "source_section": "需求注册表",
            "authority": "稳定需求注册表",
        }
        for item in requirement_records(root, config)
        for source_path, source_label in [normalize_doc_source(root, config, item.get("source", ""))]
    ]
    adrs = [
        {
            "id": item["meta"].get("id", ""),
            "title": item["title"],
            "status": item["meta"].get("status", "proposed"),
            "updated": item["meta"].get("updated", "未声明"),
            "requirements": list_field(item["meta"].get("requirements", "")),
            "path": item["path"].relative_to(docs).as_posix(),
            "source_path": item["path"].relative_to(docs).as_posix(),
        }
        for item in adr_documents(root, config)
    ]
    e2e = [
        {
            "id": item["meta"].get("id", ""),
            "title": item["title"],
            "status": item["meta"].get("status", "draft"),
            "environment": item["meta"].get("environment_level", "未声明"),
            "requirements": list_field(item["meta"].get("requirements", "")),
            "acceptance": acceptance_ids(item["text"]),
            "path": item["path"].relative_to(docs).as_posix(),
        }
        for item in current_e2e_documents(root, config)
    ]
    decisions = [
        {
            "id": item.get("id", ""),
            "title": item.get("title", "未命名决策"),
            "decision": item.get("decision", "未填写"),
            "rationale": item.get("rationale", "未填写"),
            "status": item.get("status", "proposed"),
            "requirements": list_field(str(item.get("requirements", ""))),
            "affected": item.get("affected", "未填写"),
            "confirmed_by": item.get("confirmed_by"),
            "confirmed_at": item.get("confirmed_at"),
            "source_path": decisions_path(root, config).relative_to(docs).as_posix(),
        }
        for item in decision_records(root, config)
    ]
    governance = browser_governance(root, config, features, authority_digest_value)
    delivery_targets = browser_delivery_targets(root, config, features)
    governance["delivery_targets"] = delivery_targets
    findings = browser_findings(root, config, documents, directories, features, governance, authority_digest_value)
    finding_by_object: dict[str, int] = {}
    for finding in findings:
        finding_by_object[finding["object_id"]] = finding_by_object.get(finding["object_id"], 0) + 1
    for directory in directories:
        directory["finding_count"] = sum(
            1
            for finding in findings
            if finding["source_path"] == directory["path"] or finding["source_path"].startswith(directory["path"] + "/")
        )
        directory["status"] = "阻塞" if directory["finding_count"] else "结构就绪"
    task_packets = browser_task_packets(features, findings, authority_digest_value, str(config["current_version"]), generation_stamp)
    execution_plan = browser_execution_plan(task_packets)
    # Keep the legacy top-level version collection aligned with the same
    # registered portfolio used by 工作台、总览 and project-wide relations.
    versions = []
    for card in version_portfolio.get("versions", []):
        version_id = str(card.get("id", ""))
        source = (card.get("sources") or [])[0] if card.get("sources") else {}
        versions.append(
            {
                "id": version_id,
                "title": card.get("goal") or f"{version_id} 版本",
                "status": "current" if version_id == str(config["current_version"]) else card.get("planning_status", "planning"),
                "role": card.get("role", "unknown"),
                "updated": card.get("updated", "未声明"),
                "path": card.get("overview_path") or source.get("source_path", ""),
                "summary": card.get("goal") or "版本范围、实现和证据分别以对应权威文档为准。",
            }
        )
    if not versions:
        versions = [{
            "id": config["current_version"],
            "title": f"{config['current_version']} 当前版本",
            "status": "current",
            "role": "active",
            "updated": max((item.get("updated", "") for item in features), default="未声明"),
            "path": f"02-产品与版本/当前版本/{config['current_version']}-版本总览.md",
            "summary": "当前活动版本；范围、实现和证据分别以对应权威文档为准。",
        }]
    relations = browser_relations(documents, directories, features, requirements, decisions, adrs, e2e, versions, task_packets)
    blocked_features = [item for item in features if any(f["object_id"] == item.get("id") and f["severity"] == "blocking" for f in findings)]
    stage = "release"
    for gate in governance.get("gates", []):
        if gate.get("status") == "blocked":
            stage = gate["id"]
            break
    current_feature = blocked_features[0] if blocked_features else (features[0] if features else None)
    governance["finding_count"] = len(findings)
    governance["open_finding_count"] = sum(1 for item in findings if item["status"] == "open")
    governance["authority_digest"] = authority_digest_value
    governance["authority_file_count"] = authority_file_count
    snapshots = browser_snapshots(root, config)
    change_summary = browser_change_summary(snapshots)
    evolution_view = browser_evolution_view(root, config)
    for feature in features:
        track_id = feature.get("evolution_track", "none")
        feature["future_versions"] = sorted(
            {
                item["version"]
                for item in evolution_view["milestones"]
                if track_id not in {"", "none"} and item["track_id"] == track_id and item["version"] != config["current_version"]
            }
        )
    maps = browser_map_views(
        root,
        config,
        documents,
        directories,
        features,
        requirements,
        decisions,
        adrs,
        e2e,
        versions,
        task_packets,
        relations,
    )
    workbench_view = browser_workbench_view(config, current_feature, findings, task_packets, governance)
    workbench_view["active_execution_version"] = str(config["current_version"])
    workbench_view["version_portfolio"] = version_portfolio
    project_features = browser_project_features(root, config, version_portfolio, features)
    project_versions = [
        {
            "id": item.get("id", ""),
            "title": item.get("goal", "") or f"{item.get('id', '')} 版本",
            "status": item.get("planning_status", "unknown"),
            "role": item.get("role", "unknown"),
            "goal": item.get("goal", ""),
            "overview_path": item.get("overview_path", ""),
            "sources": item.get("sources", []),
        }
        for item in version_portfolio.get("versions", [])
    ]
    # The overview is the portfolio surface: its identity and summary counters
    # must describe every registered version.  Keep the active-only collections
    # below untouched because Gates, Goals, and delivery progress are execution
    # inputs for config.current_version only.
    portfolio_requirements: list[dict] = []
    portfolio_decisions: list[dict] = []
    seen_requirement_ids: set[str] = set()
    seen_decision_ids: set[str] = set()
    for version_card in version_portfolio.get("versions", []):
        version_id = str(version_card.get("id", ""))
        if not version_id:
            continue
        for item in requirement_records(root, config, version_id):
            requirement_id = str(item.get("id", ""))
            if requirement_id and requirement_id not in seen_requirement_ids:
                seen_requirement_ids.add(requirement_id)
                portfolio_requirements.append({**item, "version": version_id})
        for item in decision_records(root, config, version_id):
            decision_id = str(item.get("id", ""))
            if decision_id and decision_id not in seen_decision_ids:
                seen_decision_ids.add(decision_id)
                portfolio_decisions.append({**item, "version": version_id})
    timelines = []
    for feature in project_features:
        feature_findings = [
            item for item in findings if item.get("status") == "open" and item.get("object_id") == feature.get("id")
        ]
        track_id = feature.get("evolution_track", "none")
        milestones = [
            item for item in evolution_view["milestones"] if track_id not in {"", "none"} and item["track_id"] == track_id
        ]
        is_active_feature = str(feature.get("version", "")) == str(config["current_version"])
        implementation = feature.get("implementation_signal", {}) if is_active_feature else {}
        development_evidence = next(
            (item for item in governance.get("evidence", []) if item.get("type") == "development"),
            {},
        ) if is_active_feature else {}
        automated_verification = implementation.get("automated_verification", "not_run")
        if is_active_feature and development_evidence.get("result") == "passed":
            automated_verification = "passed" if development_evidence.get("freshness") == "fresh" else "stale"
        current_gap = implementation.get("gap", "历史版本没有独立机器证据或冻结工程快照，当前实现状态待确认。")
        if feature_findings and is_active_feature:
            current_gap = feature_findings[0].get("reason", current_gap)
        feature_packet = next((item for item in task_packets if item.get("feature_id") == feature.get("id")), None)
        if any(item.get("severity") in {"blocking", "high"} for item in feature_findings) and is_active_feature:
            current_gate = "blocked"
        elif feature_packet and feature_packet.get("status") == "ready" and is_active_feature:
            current_gate = "ready"
        else:
            current_gate = "unknown"
        timelines.append(
            {
                "feature_id": feature.get("id", ""),
                "title": feature.get("title", ""),
                "version": feature.get("version", config["current_version"]),
                "goal": feature.get("summary", ""),
                "domain": feature.get("domain", ""),
                "risk": feature.get("risk", ""),
                "current_implementation": {
                    "backend": implementation.get("backend", "unknown"),
                    "frontend": implementation.get("frontend", "unknown"),
                    "data": implementation.get("data", "unknown"),
                    "automated_verification": automated_verification,
                },
                "implementation_paths": implementation.get("paths", {}),
                "existing_paths": implementation.get("existing_paths", {}),
                "current_gap": current_gap,
                "current_gate": current_gate,
                "dependencies": feature.get("dependencies", []),
                "milestones": milestones,
                "evidence_freshness": development_evidence.get("freshness", "unknown"),
                "evidence_summary": governance.get("evidence_binding", {}),
                "sources": [
                    browser_source(feature.get("path", ""), "功能规格", feature.get("id", ""), "功能行为与验收"),
                    *(
                        [browser_source(
                            f"02-产品与版本/当前版本/{config['current_version']}-实现状态.md",
                            "实现状态",
                            feature.get("id", ""),
                            "代码、测试和证据派生状态",
                        )]
                        if is_active_feature
                        else []
                    ),
                ],
            }
        )
    entity_by_id: dict[str, dict] = {}
    for map_view in maps.values():
        for node in map_view.get("nodes", []):
            entity_by_id[node["id"]] = {
                "id": node["id"],
                "label": node["label"],
                "type": node["type"],
                "sources": node.get("sources", []),
            }
    delivery_progress_counts = {
        status: 0
        for status in ["not_started", "implementing", "local_verified", "staging_verified", "released", "unknown"]
    }
    delivery_progress_items = []
    implementation_status_path = f"02-产品与版本/当前版本/{config['current_version']}-实现状态.md"
    for feature in features:
        feature_status = str(feature.get("status", "unknown"))
        signal = feature.get("implementation_signal", {})
        declared_paths = sum(len(items) for items in (signal.get("paths") or {}).values())
        existing_paths = sum(len(items) for items in (signal.get("existing_paths") or {}).values())
        if feature_status in {"released", "staging_verified", "local_verified"}:
            delivery_status = feature_status
            basis = f"功能实现状态为 {feature_status}；机器证据仍按提交和构建新鲜度独立判断"
        elif feature_status == "implementing" or existing_paths:
            delivery_status = "implementing"
            basis = f"检测到 {existing_paths} 个已存在工程落点；尚未取得已验证或已发布状态"
        elif feature_status in {"planning", "draft", "ready"} or declared_paths:
            delivery_status = "not_started"
            basis = f"已声明 {declared_paths} 个工程落点，当前未检测到实现落点"
        else:
            delivery_status = "unknown"
            basis = "功能状态和工程落点不足以判断交付进度"
        delivery_progress_counts[delivery_status] += 1
        delivery_progress_items.append(
            {
                "feature_id": feature.get("id", ""),
                "title": feature.get("title", ""),
                "status": delivery_status,
                "basis": basis,
                "sources": [
                    browser_source(feature.get("path", ""), "实现与验证", feature.get("id", ""), "功能声明与工程落点"),
                    browser_source(implementation_status_path, "实现状态", feature.get("id", ""), "代码、测试和证据派生状态"),
                ],
            }
        )

    overview_view = {
        "scope": {
            "label": "全版本",
            "active_execution_version": str(config["current_version"]),
        },
        "stats": {
            "documents": len(documents),
            "machine_reports": len([path for path in docs.rglob("*.json") if "报告" in path.parts]),
            "versions": len(version_portfolio.get("versions", [])),
            "features": len(project_features),
            "requirements": len(portfolio_requirements),
            "accepted_decisions": sum(1 for item in portfolio_decisions if item.get("status") == "accepted"),
        },
        "product_architecture": maps["product_architecture"],
        "core_flow": maps["core_flow"],
        "version_chain": maps["version_roadmap"],
        "development_progress": {
            "counts": delivery_progress_counts,
            "items": delivery_progress_items,
        },
        "accepted_decisions": [item for item in portfolio_decisions if item.get("status") == "accepted"],
        "authority_entries": [
            {"title": item["title"], "path": item["path"], "authority": item["authority"]}
            for item in documents
            if re.search(r"产品蓝图|版本总览|总体架构|数据模型|测试策略|发布.*清单", item["title"])
        ][:8],
    }
    views = {
        "workbench": workbench_view,
        "overview": overview_view,
        "reader": {
            "document_count": len(documents),
            "directory_count": len(directories),
            "navigation": reader_navigation,
        },
        "maps": maps,
        "evolution": evolution_view,
        "timelines": timelines,
    }
    goal_readiness = browser_goal_readiness(task_packets, findings, authority_digest_value)
    goal_runtime = browser_goal_runtime(root, config)
    goal_readiness["execution_plan"] = execution_plan
    goal_readiness["document_sync_policy"] = {
        "mode": "authority_first",
        "trigger": "权威文档、ChangeSet、ADR、AC、实现落点或验证命令变化",
        "required_action": "停止受影响任务，更新权威来源并重新运行 index、check、相关 gate 和 prepare-goal",
    }
    workbench_view["execution_plan"] = execution_plan
    workbench_view["document_sync_policy"] = goal_readiness["document_sync_policy"]
    workbench_view["goal_runtime"] = goal_runtime
    payload = {
        "schema_version": 12,
        "generated_at": generation_stamp,
        "tool_version": TOOL_VERSION,
        "source_commit": source_commit or "",
        "authority_digest": authority_digest_value,
        "project": {
            "name": config["project_name"],
            "code": config["project_code"],
            "current_version": config["current_version"],
            "profile": config["profile"],
        },
        "documents": documents,
        "directories": directories,
        "entities": sorted(entity_by_id.values(), key=lambda item: item["id"]),
        "features": features,
        "project_features": project_features,
        "project_versions": project_versions,
        "requirements": requirements,
        "relations": relations,
        "findings": findings,
        "task_packets": task_packets,
        "versions": versions,
        "decisions": decisions,
        "adrs": adrs,
        "e2e": e2e,
        "governance": governance,
        "delivery_targets": delivery_targets,
        "snapshots": snapshots,
        "evidence_freshness": governance.get("evidence_freshness", {}),
        "views": views,
        "change_summary": change_summary,
        "goal_readiness": goal_readiness,
        "goal_runtime": goal_runtime,
        "workbench": workbench_view,
    }
    enrich_browser_source_sections(payload, documents)
    return payload


def render_browser_data(root: Path, config: dict) -> str:
    payload = json.dumps(browser_payload(root, config), ensure_ascii=False, separators=(",", ":")).replace("</", "<\\/")
    return f"// generated by daoge-docs; 请修改权威源后运行 index，不要直接编辑\nwindow.DAOGE_DOC_BROWSER_DATA=Object.freeze({payload});\n"


def browser_data_payload(content: str) -> dict | None:
    """Parse the generated browser payload without treating it as authority."""
    prefix = "window.DAOGE_DOC_BROWSER_DATA=Object.freeze("
    if prefix not in content or not content.rstrip().endswith(");"):
        return None
    try:
        payload = json.loads(content.split(prefix, 1)[1].rsplit(");", 1)[0])
    except json.JSONDecodeError:
        return None
    return payload if isinstance(payload, dict) else None


def browser_data_semantic_payload(content: str) -> dict | None:
    """Parse browser data while removing index-run metadata from freshness checks."""
    payload = browser_data_payload(content)
    if payload is None:
        return None
    payload = json.loads(json.dumps(payload, ensure_ascii=False))
    # A commit containing only derived artifacts necessarily advances HEAD after index.
    # These fields describe that index run, not its authoritative inputs.
    payload.pop("generated_at", None)
    payload.pop("source_commit", None)
    for packet in payload.get("task_packets", []):
        if isinstance(packet, dict):
            packet.pop("generated_at", None)
    for key in ["evidence_freshness", "governance"]:
        value = payload.get(key)
        if isinstance(value, dict):
            freshness = value.get("evidence_freshness") if key == "governance" else value
            if isinstance(freshness, dict):
                freshness.pop("current_commit", None)
    return payload


def generated_document_is_current(root: Path, config: dict, path: Path, actual: str, expected: str) -> bool:
    if actual == expected:
        return True
    if path.name != "产品文档浏览器-文档数据.js":
        return False
    raw_actual_payload = browser_data_payload(actual)
    actual_payload = browser_data_semantic_payload(actual)
    expected_payload = browser_data_semantic_payload(expected)
    return (
        raw_actual_payload is not None
        and actual_payload is not None
        and actual_payload == expected_payload
    )


def render_browser_html(config: dict) -> str:
    template = (BROWSER_TEMPLATES / "产品文档浏览器.html").read_text(encoding="utf-8")
    return render(
        template,
        {
            "PROJECT_NAME": html.escape(str(config["project_name"])),
            "PROJECT_CODE": html.escape(str(config["project_code"])),
            "VERSION": html.escape(str(config["current_version"])),
            "PYTHON_COMMAND": project_python_command(),
        },
    )


def render_analysis_html() -> str:
    return '''<!-- generated by daoge-docs; 请修改 Skill 方法论后重新生成，不要直接编辑 -->
<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>文档驱动开发分析手册</title><style>body{max-width:920px;margin:40px auto;padding:0 24px;color:#17202a;font:16px/1.75 -apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei",sans-serif}h1{font-size:32px}h2{margin-top:34px;border-bottom:1px solid #dfe3e6;padding-bottom:8px}table{border-collapse:collapse;width:100%}th,td{border:1px solid #dfe3e6;padding:10px;text-align:left}code{background:#f1f3f5;padding:2px 5px}</style></head><body><h1>文档驱动开发分析手册</h1><p>本文是 DAOGE Docs 方法论的只读入口，不保存项目业务事实。</p><h2>四个目标属性</h2><table><tr><th>属性</th><th>判定</th></tr><tr><td>确定性</td><td>相同输入、状态和规则版本得到相同结果。</td></tr><tr><td>指向性</td><td>变更指向版本、需求、AC、实现和证据。</td></tr><tr><td>稳定性</td><td>并发、失败、迁移与回滚不破坏不变量。</td></tr><tr><td>可解释性</td><td>结果可追溯规则、分支、状态、副作用和证据。</td></tr></table><h2>权威链</h2><p>产品蓝图 → 当前版本 → 稳定需求 → 功能规格 → API/数据/设计 → AC/E2E → 实现 → 机器证据 → 发布批准。</p><h2>四级门禁</h2><ol><li>Discovery：事实是否查明。</li><li>Version Ready：版本输入是否闭环。</li><li>Feature Ready：单功能是否可以确定性实现。</li><li>Release：当前提交和构建是否有发布级证据。</li></ol><h2>核心纪律</h2><p>每类事实只有一个权威来源；未知内容显式阻塞；失败证据不可覆盖；工具不自行批准任何业务或发布决定。</p></body></html>'''


def generated_documents(root: Path, config: dict) -> dict[Path, str]:
    docs = docs_root(root, config)
    version = str(config["current_version"])
    candidates = {
        docs / "01-项目概览" / "项目输入与约束总账.md": render_project_inputs_ledger(root, config),
        docs / "03-功能规格" / version / "README.md": render_feature_index(root, config),
        docs / "03-功能规格" / version / "功能查找表.md": render_feature_lookup(root, config),
        docs / "03-功能规格" / version / "功能风险分级.md": render_risk_index(root, config),
        docs / "03-功能规格" / version / "技术设计索引.md": render_design_index(root, config),
        docs / "03-功能规格" / version / f"00-{version}需求编号.md": render_requirement_index(root, config),
        docs / "03-功能规格" / version / f"00-{version}需求追踪矩阵.md": render_trace_matrix(root, config),
        docs / "02-产品与版本" / "当前版本" / f"{version}-实现状态.md": render_implementation_status(root, config),
        docs / "05-测试与发布" / "端到端验收" / "用例矩阵.md": render_e2e_matrix(root, config),
        docs / "06-决策记录" / "ADR" / "README.md": render_adr_index(root, config),
        docs / "06-决策记录" / f"{version}-冻结决策.md": render_frozen_decisions(root, config),
        docs / "02-产品与版本" / "图表" / "功能演进-版本主链路.svg": render_version_flow_svg(root, config),
        docs / "02-产品与版本" / "图表" / "功能演进-能力热力图.svg": render_capability_heatmap_svg(root, config),
        docs / "02-产品与版本" / "图表" / "功能演进-门禁依赖图.svg": render_gate_flow_svg(),
        docs / "90-参考资料" / "产品文档浏览器-文档数据.js": render_browser_data(root, config),
        docs / "90-参考资料" / "产品文档浏览器.html": render_browser_html(config),
        docs / "90-参考资料" / "文档驱动开发分析手册.html": render_analysis_html(),
    }
    allowed = {
        docs / rendered_profile_path(item, values_for(config))
        for item in profile_documents(str(config["profile"]))
        if item.get("generated")
    }
    return {path: content for path, content in candidates.items() if path in allowed}


def generate_indexes(root: Path, config: dict) -> list[Path]:
    generated: list[Path] = []
    for path, content in generated_documents(root, config).items():
        write_generated(path, content)
        generated.append(path)
    browser_data = docs_root(root, config) / "90-参考资料" / "产品文档浏览器-文档数据.js"
    if browser_data in generated:
        write_generated(browser_data, render_browser_data(root, config))
    return generated


def command_init(args: argparse.Namespace) -> dict:
    root = project_root(args.root)
    code = validate_project_code(args.project_code)
    version = safe_segment(args.version, "版本号")
    name = args.project_name.strip()
    profile = args.profile.strip().lower()
    if not name:
        raise DocsError("项目名称不能为空")
    if profile not in PROFILES:
        raise DocsError(f"profile 必须是：{', '.join(sorted(PROFILES))}")
    config_path = root / CONFIG_NAME
    target_docs = root / "docs"
    if config_path.exists():
        raise DocsError(f"项目已经初始化：{config_path}；如需更新工具请运行 upgrade")
    if target_docs.exists() and any(target_docs.iterdir()) and not args.merge:
        raise DocsError("docs/ 已包含文件；确认保留现有内容后使用 --merge 补齐缺失文件")

    config = {
        "schema_version": 2,
        "tool_version": TOOL_VERSION,
        "project_name": name,
        "project_code": code,
        "current_version": version,
        "docs_root": "docs",
        "profile": profile,
        "language": "zh-CN",
        "statuses": STATUSES,
        "release_evidence_types": sorted(EVIDENCE_TYPES),
    }
    created, skipped = materialize_profile(root, config, version)
    ensure_requirements(root, config, version)
    created.append(str(requirements_path(root, config, version).relative_to(root)))
    ensure_decisions(root, config, version)
    created.append(str(decisions_path(root, config, version).relative_to(root)))
    ensure_project_inputs(root, config)
    created.append(str(project_inputs_path(root, config).relative_to(root)))
    evidence_selector = root / ".daoge-docs" / "evidence.json"
    if not evidence_selector.exists():
        write_json(
            evidence_selector,
            {"schema_version": 1, "version": version, "selected": {item: None for item in sorted(EVIDENCE_TYPES)}},
        )
        created.append(str(evidence_selector.relative_to(root)))
    tool_created, tool_skipped = vendor_tooling(root)
    created.extend(tool_created)
    skipped.extend(tool_skipped)
    write_json(config_path, config)
    created.append(CONFIG_NAME)

    if args.github_actions:
        workflow = root / ".github" / "workflows" / "daoge-docs.yml"
        if workflow.exists():
            skipped.append(str(workflow.relative_to(root)))
        else:
            source = INTEGRATION_TEMPLATES / "github-actions.yml"
            write_new(workflow, render(source.read_text(encoding="utf-8"), values_for(config)))
            created.append(str(workflow.relative_to(root)))
    generated = generate_indexes(root, config)
    return {
        "状态": "已初始化",
        "项目根目录": str(root),
        "Profile": profile,
        "新建文件数": len(set(created)),
        "保留已有文件数": len(set(skipped)),
        "派生文件": [str(path.relative_to(root)) for path in generated],
        "下一步": "先完成项目调研与权威文档，再运行 gate --stage discovery 和 gate --stage version-ready。",
    }


def command_upgrade(args: argparse.Namespace) -> dict:
    root = project_root(args.root)
    config = load_config(root)
    if args.profile:
        config["profile"] = args.profile
    config["schema_version"] = 2
    config["tool_version"] = TOOL_VERSION
    config["language"] = "zh-CN"
    created, skipped = vendor_tooling(root, overwrite=True)
    doc_created, doc_skipped = materialize_profile(root, config, str(config["current_version"]))
    created.extend(doc_created)
    skipped.extend(doc_skipped)
    ensure_requirements(root, config, str(config["current_version"]))
    ensure_project_inputs(root, config)
    write_json(root / CONFIG_NAME, config)
    generated = generate_indexes(root, config)
    return {
        "状态": "工具与文档清单已升级",
        "版本": TOOL_VERSION,
        "Profile": config["profile"],
        "写入文件数": len(set(created)),
        "保留项目文件数": len(set(skipped)),
        "派生文件": [str(path.relative_to(root)) for path in generated],
    }


def command_install_integrations(args: argparse.Namespace) -> dict:
    root = project_root(args.root)
    config = load_config(root)
    requested = sorted(set(args.target or ["github", "vscode", "agents"]))
    targets = {
        "github": [
            ("github-actions.yml", Path(".github/workflows/daoge-docs.yml")),
            ("pull-request-template.md", Path(".github/pull_request_template.md")),
        ],
        "vscode": [("vscode-tasks.json", Path(".vscode/tasks.json"))],
        "agents": [("AGENTS-snippet.md", Path("AGENTS.md"))],
    }
    created: list[str] = []
    skipped: list[str] = []
    for target in requested:
        for template_name, relative in targets[target]:
            destination = root / relative
            if destination.exists():
                skipped.append(relative.as_posix())
                continue
            source = INTEGRATION_TEMPLATES / template_name
            if not source.exists():
                raise DocsError(f"缺少集成模板：{source}")
            write_new(destination, render(source.read_text(encoding="utf-8"), values_for(config)))
            created.append(relative.as_posix())
    return {
        "状态": "开发集成已安装",
        "目标": requested,
        "新建": created,
        "保留已有": skipped,
        "说明": "只新增缺失文件；已有 CI、PR、IDE 或 AGENTS 配置未被覆盖。",
    }


def command_new_version(args: argparse.Namespace) -> dict:
    root = project_root(args.root)
    config = load_config(root)
    version = safe_segment(args.version, "版本号")
    old_version = str(config["current_version"])
    if version == old_version:
        raise DocsError(f"{version} 已经是当前版本")
    if args.activate:
        config["current_version"] = version
    created, skipped = materialize_profile(root, config, version)
    path = ensure_requirements(root, config, version)
    if str(path.relative_to(root)) not in created:
        created.append(str(path.relative_to(root)))
    decision_path = ensure_decisions(root, config, version)
    if str(decision_path.relative_to(root)) not in created:
        created.append(str(decision_path.relative_to(root)))
    if args.activate:
        selector = root / ".daoge-docs" / "evidence.json"
        write_json(selector, {"schema_version": 1, "version": version, "selected": {item: None for item in sorted(EVIDENCE_TYPES)}})
        write_json(root / CONFIG_NAME, config)
        generated = generate_indexes(root, config)
    else:
        generated = []
    return {
        "状态": "已创建版本文档",
        "版本": version,
        "已设为当前版本": bool(args.activate),
        "新建": created,
        "跳过": skipped,
        "派生文件": [str(path.relative_to(root)) for path in generated],
    }


def command_new_future_version(args: argparse.Namespace) -> dict:
    root = project_root(args.root)
    config = load_config(root)
    version = safe_segment(args.version, "后续版本号").upper()
    if not re.fullmatch(r"V\d+", version):
        raise DocsError("后续版本号必须使用 V 加正整数，例如 V2")
    if version == str(config["current_version"]):
        raise DocsError("后续版本不能与当前版本相同；需要建立活动版本空间时使用 new-version")
    if any(item["version"] == version for item in future_version_plan_records(root, config)):
        raise DocsError(f"{version} 已有后续版本规划入口；如需变更请更新该权威文档或建立替代关系")
    name = safe_segment(args.name, "后续版本名称")
    directory = docs_root(root, config) / "02-产品与版本" / "后续版本" / f"{version}-{name}"
    path = directory / f"{version}-版本总览.md"
    readme = directory / "README.md"
