def command_new_feature(args: argparse.Namespace) -> dict:
    root = project_root(args.root)
    config = load_config(root)
    number = int(args.number)
    if number < 1 or number > 999:
        raise DocsError("功能编号必须在 1 至 999 之间")
    risk = args.risk.strip().lower()
    if risk not in RISKS:
        raise DocsError(f"风险等级必须是：{', '.join(sorted(RISKS))}")
    evolution_track = args.evolution_track.strip().upper()
    if evolution_track and not re.fullmatch(r"TRACK-[A-Z0-9][A-Z0-9-]*", evolution_track):
        raise DocsError("能力主线必须使用 TRACK-* 稳定 ID，例如 TRACK-ORDER")
    name = safe_segment(args.name, "功能名称")
    domain = safe_segment(args.domain, "领域")
    forbidden_paths = normalize_goal_paths(args.forbidden_paths)
    invalid_forbidden = [path for path in forbidden_paths if not valid_goal_path(path)]
    if invalid_forbidden:
        raise DocsError("禁止路径必须是仓库内相对路径且至少包含目录层级：" + ", ".join(invalid_forbidden))
    feature_id = f"{config['project_code']}-FR-{number:03d}"
    if any(record["meta"].get("id") == feature_id for record in feature_documents(root, config)):
        raise DocsError(f"功能 ID 已存在：{feature_id}")
    version = str(config["current_version"])
    filename_number = f"{number:02d}" if number < 100 else f"{number:03d}"
    directory = docs_root(root, config) / "03-功能规格" / version / domain
    if not (directory / "README.md").exists():
        raise DocsError(f"领域尚未建立：请先运行 new-domain --name {args.domain!r}")
    main_path = directory / f"{filename_number}-{name}.md"
    values = {
        "FEATURE_ID": feature_id,
        "FEATURE_NUMBER": filename_number,
        "FEATURE_NAME": args.name.strip(),
        "VERSION": version,
        "RISK": risk,
        "RISK_REASON": args.risk_reason.strip(),
        "DOMAIN": args.domain.strip(),
        "EVOLUTION_TRACK": evolution_track or "none",
        "KEYWORDS": args.keywords.strip() or args.name.strip(),
        "REQUIREMENTS": args.requirements.strip() or "none",
        "FORBIDDEN_PATHS": args.forbidden_paths.strip() or "none",
        "DATE": today(),
    }
    main_template = (DOCUMENT_TEMPLATES / "功能主文档.md").read_text(encoding="utf-8")
    write_new(main_path, render(main_template, values))
    created = [main_path]
    if risk == "high":
        design_path = directory / f"{filename_number}-{name}-技术设计.md"
        template = (DOCUMENT_TEMPLATES / "高风险技术设计.md").read_text(encoding="utf-8")
        write_new(design_path, render(template, values))
        created.append(design_path)
    generate_indexes(root, config)
    return {"状态": "已创建功能规格", "功能 ID": feature_id, "文件": [str(path.relative_to(root)) for path in created]}


def command_new_requirement(args: argparse.Namespace) -> dict:
    root = project_root(args.root)
    config = load_config(root)
    source_path, _ = normalize_doc_source(root, config, args.source)
    if not source_path:
        raise DocsError("需求权威来源必须指向项目 docs 内真实存在的文件")
    requirement_type = args.type.upper()
    if requirement_type not in REQUIREMENT_TYPES:
        raise DocsError("独立注册表仅允许 NFR 或 RG；FR 请使用 new-feature 创建")
    path = ensure_requirements(root, config, str(config["current_version"]))
    data = read_json(path, "需求注册表")
    items = data.setdefault("items", [])
    existing = [item for item in items if isinstance(item, dict) and item.get("type") == requirement_type]
    number = args.number or max(
        [int(match.group(1)) for item in existing if (match := re.fullmatch(rf"{re.escape(config['project_code'])}-{requirement_type}-(\d{{3}})", str(item.get('id', ''))))],
        default=0,
    ) + 1
    requirement_id = f"{config['project_code']}-{requirement_type}-{number:03d}"
    if any(item.get("id") == requirement_id for item in items if isinstance(item, dict)):
        raise DocsError(f"需求 ID 已存在：{requirement_id}")
    items.append(
        {
            "id": requirement_id,
            "type": requirement_type,
            "title": args.name.strip(),
            "status": "draft",
            "source": source_path,
            "verification": args.verification.strip(),
            "updated": today(),
        }
    )
    write_json(path, data)
    generate_indexes(root, config)
    return {"状态": "已注册需求", "需求 ID": requirement_id, "注册表": str(path.relative_to(root))}


